INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(31, 'koKR', '', '$GUkończyłeś:Ukończyłaś; wszystkie lekcje, które musi przejść każdy młody druid, zanim przybierze postać wodną. Wróć teraz do swojego nauczyciela, Turaka Runicznego Totemu, w Gromowych Urwiskach. Pokaż mu wisior i udowodnij, że $gjesteś gotów:jesteś gotowa; przyjąć to, czego ma cię nauczyć. On dokończy twoje szkolenie i pozwoli ci stać się jednym z wodą.$B$BŻegnaj, $gmłody druidzie:młoda druidko;. Jeszcze porozmawiamy.', 'Wróć do Gromowych Urwisk i pokaż Turakowi Runicznemu Totemowi wisior lwa morskiego.', '', '', '', '', '', '', 0),
(264, 'koKR', 'Dopóki śmierć nas nie rozłączy', 'Podły łajdak! Zostawił mnie dla tej swojej przeklętej krucjaty. Bo „Światło to najważniejsza broń, jaką mamy przeciw zagrożeniu ze strony nieumarłych”.$B$BA co z jego dziećmi?! A co ZE MNĄ?! Noc w noc cierpliwie na niego czekałam... zawsze na drugim miejscu po jego przeklętym obowiązku!$B$BNo to patrz, co daje ta „sprawiedliwość”, $N! On nie żyje, a ja noszę w sobie to samo, co próbował powstrzymać!$B$BWeź ten złom i połóż go na jego grobie w Grobowisku. Nie chcę mieć z tym nic wspólnego... ani z nim!', 'Połóż wisior Clarice na grobie Yuriva w Srebrzystym Borze.', '', '', '', '', '', '', 0),
(744, 'koKR', 'Przygotowania do ceremonii', '$N, mój brat wkrótce stanie przed wodzem Krwawe Kopyto, a ja mam zaszczyt wykonać dla niego pióropusz.$B$BChcę cię prosić o przysługę, póki kończę garbować te skórzane rzemienie. Nie mam czasu, by znaleźć dość piór, więc zastanawiałem się, czy nie $gzebrałbyś:zebrałabyś; ich dla mnie?$B$BPióra odpowiedniej wielkości znajdziesz u harpii, które żyją daleko na północ i północny zachód od Gromowych Urwisk. Do ukończenia wzoru potrzebuję tylko 6 lazurowych i 6 brązowych piór.', 'Zbierz 6 lazurowych piór i 6 brązowych piór, a następnie zanieś je Eyahnowi Orlemu Szponowi w Gromowych Urwiskach.', '', 'Wróć do Eyahna Orlego Szpona w Gromowych Urwiskach.', '', '', '', '', 0),
(768, 'koKR', 'Zbieranie skór', 'Witaj, $gmłodzieńcze:młoda;. Masz błysk w oku; widzę, że rwiesz się, by wrócić na równiny na łowy. Obyś $gprzyniósł:przyniosła; chwałę swojemu klanowi!$B$BPracuję ze skórami zwierząt i szyję z nich odzież i zbroje dla mieszkańców Gromowych Urwisk.$B$BJeśli zapolujesz na zwierzęta i przyniesiesz mi ich skóry, wykonam coś dla ciebie.', 'Przynieś 12 kawałków lekkiej skóry Verenowi Wysokiemu Krokowi w Gromowych Urwiskach.', '', 'Wróć do Verena Wysokiego Kroku w Gromowych Urwiskach.', '', '', '', '', 0),
(769, 'koKR', 'Torba ze skóry kodo', 'Kodo z Mulgoru są silne i wytrzymałe – to cechy, które bardzo u nas szanujemy. Jeśli znasz się na kaletnictwie i chcesz się nauczyć, jak zrobić torbę ze skóry kodo, przynieś mi materiały do mojego rzemiosła.$B$BZrób to, a podzielę się z tobą swoją wiedzą.', 'Przynieś 4 kawałki lekkiej skóry i 4 szpule grubej nici Verenowi Wysokiemu Krokowi w Gromowych Urwiskach.', '', 'Wróć do Verena Wysokiego Kroku w Gromowych Urwiskach.', '', '', '', '', 0),
(853, 'koKR', 'Aptekarka Zamah', 'Z zarodników, które mi $gdałeś:dałaś;, przygotowałem emulsję. Muszę ją teraz posłać mojej współpracowniczce, aptekarce Zamah. Jeśli jej to zaniesiesz, zaoferuje ci coś z naszych zapasów alchemicznych.$B$BZnajdziesz ją w Źródłach Objawień, w jaskini pod siedzibą szamanów Gromowych Urwisk. Ścieżka do tej jaskini jest dobrze ukryta, ale odnajdziesz ją na urwisku Wzniesienia Ducha.$B$BPośpiesz się. Emulsja zachowa moc tylko przez krótki czas, a przed jego upływem trzeba ją ponownie zapieczętować i przetworzyć.', 'Zanieś przetworzone zarodniki aptekarce Zamah w Gromowych Urwiskach, zanim upłynie czas.', '', '', '', '', '', '', 0),
(860, 'koKR', 'Sergra Ciemny Cierń', 'Jeśli chcesz kroczyć ścieżką łowcy, twoja droga prowadzi na Pustkowia. Tamtejsze zwierzęta są uparte i dzikie. Polując tam, wiele się nauczysz, a twój duch urośnie w siłę.$B$BPorozmawiaj z Sergrą Ciemny Cierń. Będzie twoją pierwszą przewodniczką na Pustkowiach.$B$BSergra przebywa na Rozdrożu. Aby do niej dotrzeć, ruszaj na wschód od Wioski Krwawego Kopyta na Pustkowia, a gdy droga się rozwidli, skręć na północ. I uważaj w drodze – Pustkowia kryją wielkie niebezpieczeństwa dla nieprzygotowanych i nieostrożnych.', 'Porozmawiaj z Sergrą Ciemny Cierń na Rozdrożu na Pustkowiach.', '', '', '', '', '', '', 0),
(886, 'koKR', 'Oazy Pustkowi', 'Druidzi z Gromowych Urwisk wyczuwają dziwną moc, która sączy się na Pustkowia na wschód od Mulgoru.$B$BTonga Runiczny Totem został wysłany, by odkryć źródło tej mocy, lecz obawiamy się, że będzie potrzebował pomocy.$B$BUdaj się na Pustkowia i porozmawiaj z Tongą. Znajdziesz go na Rozdrożu. Aby tam dotrzeć, ruszaj drogą na wschód od Wioski Krwawego Kopyta. Gdy wejdziesz na Pustkowia, skręć na północ tam, gdzie droga się rozwidla. Idź dalej na północ, a dotrzesz do Rozdroża.$B$BI nie zbaczaj z drogi, $N, bo Pustkowia to surowa kraina.', 'Porozmawiaj z Tongą Runicznym Totemem na Rozdrożu na Pustkowiach.', '', '', '', '', '', '', 0),
(914, 'koKR', 'Przywódcy Kła', 'Druidzi z Zawodzącej Pieczary, Druidzi Kła, są wynaturzeniem. Należeli do zakonu szlachetnych druidów, którzy chcieli uleczyć Pustkowia, lecz teraz pragną przekształcić tę krainę na podobieństwo swoich wypaczonych snów.$B$BDruidzi Kła mają czterech przywódców, a każdy z nich posiada klejnot snu. Ich twarze wciąż mnie nawiedzają! Pokonaj przywódców i przynieś mi ich klejnoty, a Pustkowia może znów zaznają pokoju.$B$BIdź, $N. Znajdziesz ich w głębi Zawodzącej Pieczary.', 'Przynieś klejnoty Cobrahna, Anacondry, Pythasa i Serpentisa Narze Dzikogrzywej w Gromowych Urwiskach.', '', 'Wróć do Nary Dzikogrzywej na Złotych Równinach w Mulgorze.', '', '', '', '', 0),
(962, 'koKR', 'Wężokwiat', 'Królewskie Zakłady Chemiczne, mające siedzibę w wielkim Podmieście Lordaeronu, przysłały mnie tu w bardzo konkretnej sprawie, $n. Może zechcesz pomóc mnie, a tym samym Mrocznej Pani w naszych staraniach na rzecz Porzuconych.$b$bNiedawno badałam rzadki okaz rośliny zwanej wężokwiatem. Sądzę, że ziele to w większych ilościach ma ogromny potencjał.$b$bNiestety wężokwiat rośnie tylko w najciemniejszych zakamarkach Zawodzącej Pieczary, niebezpiecznego systemu jaskiń na Pustkowiach.', 'Aptekarka Zamah w Gromowych Urwiskach chce, żebyś $gzebrał:zebrała; 10 sztuk wężokwiatu.', '', 'Wróć do aptekarki Zamah w Mulgorze.', '', '', '', '', 0),
(1049, 'koKR', 'Kompendium Poległych', 'Krąg Ziemi miał czyste zamiary wobec naszych dotkniętych zarazą braci. Lecz któż zna pobudki tych, którzy szepczą do uszu Rady Starszych?$b$bPorzuceni, z którymi się sprzymierzyliśmy, mają za sobą historię pełną podstępów. Zbyt pochopnie zawarliśmy ten pakt. Może Kairn postąpiłby mądrze, gdyby posłuchał ostrzeżeń z Orgrimmaru.$b$bW głębi Szkarłatnego Klasztoru spoczywa Kompendium Poległych, strzeżone przez oszalałych ludzkich fanatyków. Ich metody zrodziło szaleństwo, lecz ich badania mogą okazać się przydatne.', 'Zdobądź Kompendium Poległych z Klasztoru w Polanach Tirisfal i wróć do mędrca Poszukiwacza Prawdy w Gromowych Urwiskach.', '', 'Wróć do mędrca Poszukiwacza Prawdy w Gromowych Urwiskach.', '', '', '', '', 0),
(1063, 'koKR', 'Wiedźma starszyzny', 'Aby naprawdę zadbać o duchy Szponogłazów, musimy zasięgnąć rady starszyzny taurenów.$B$BNie znam imion wielu ich przywódców, ale o jednej słyszałam: o Magacie. Podobno jest bardzo stara i wie wiele. Jeśli ktokolwiek zdoła zjednać duchową pomoc taurenów, to właśnie ona.$B$BMagata mieszka w stolicy taurenów, Gromowych Urwiskach, na Wzniesieniu Starszych – północno-wschodnim urwisku miasta. Porozmawiaj z Magatą i opowiedz jej o niedoli Gór Szponogłazów.', 'Porozmawiaj z Magatą w Gromowych Urwiskach.', '', '', '', '', '', '', 0),
(1064, 'koKR', 'Pomoc Porzuconych', 'Taureni są związani z ziemią, a wieść o niedoli Szponogłazów sprawia mi ból. Obawiam się jednak, że aby uleczyć ziemię, musimy najpierw usunąć toczącą ją chorobę.$B$BCzyż to nie szczęście, że Porzuceni są naszymi sojusznikami? Wiedzą wiele o chorobach. Wierzę, że mogą nam pomóc, a czyniąc to, umocnią zaufanie między naszymi ludami.$B$BPorozmawiaj z aptekarką Zamah. To uczona i wysłanniczka Porzuconych. Znajdziesz ją w Źródłach Objawień pod Wzniesieniem Ducha.', 'Porozmawiaj z aptekarką Zamah w Źródłach Objawień w Gromowych Urwiskach.', '', '', '', '', '', '', 0),
(1065, 'koKR', 'Podróż do Smolnego Młyna', 'Aby pozbyć się spółki Gitgeszeft ze Szponogłazów, musimy sięgnąć po środki ostateczne. Ostateczne, lecz bez rozlewu krwi.$B$BMój kolega może mieć narzędzie, jakiego nam trzeba. Nazywa się Lydon i mieszka w Smolnym Młynie w Międzygórzu, w dalekiej krainie Lordaeron.$B$BAby dotrzeć do Międzygórza, leć sterowcem do naszej stolicy, Podmiasta. Potem ruszaj na północ do Polan Tirisfal, na południowy zachód do Srebrzystego Boru i na południe do Międzygórza.$B$BOdszukaj Lydona i zanieś mu ten liścik. Opisuje, czego potrzebujemy.', 'Zanieś liścik od Zamah aptekarzowi Lydonowi w Smolnym Młynie.', '', '', '', '', '', '', 0),
(1066, 'koKR', 'Krew niewinnych', 'Stworzę toksynę, która wysączy ze spółki Gitgeszeft skłonność do przemocy i uczyni jej ludzi słabymi i potulnymi. To powinno rozwiązać problem Hordy w Szponogłazach, nieprawdaż?$B$BLecz do stworzenia toksyny potrzebuję krwi niewinnych, a to składnik trudny do zdobycia.$B$BNa szczęście Syndykat, banda ludzkich rozbójników z tej okolicy, zatrudnia magów cienia... a ci magowie zbierają niewinną krew do własnych, podejrzanych celów.$B$BMagów cienia z Syndykatu znajdziesz w Twierdzy Durnhold na południowym wschodzie.', 'Przynieś 5 fiolek niewinnej krwi aptekarzowi Lydonowi w Smolnym Młynie.', '', '', '', '', '', '', 0),
(1067, 'koKR', 'Powrót do Gromowych Urwisk', 'Oto toksyna. Jeśli użyjesz jej przeciw spółce Gitgeszeft, powinna przynieść korzystne, a może nawet zaraźliwe skutki. Muszę przyznać, że to ekscytujące widzieć swoją pracę zastosowaną w terenie!$B$BZanim jednak jej użyjesz, zanieś ją aptekarce Zamah. Musi opracować sposób podania toksyny, by w pełni wykorzystać jej działanie.', 'Zanieś toksynę Lydona aptekarce Zamah w Gromowych Urwiskach.', '', '', '', '', '', '', 0),
(1086, 'koKR', 'Lądowisko fruwających maszyn', 'Toksyna jest gotowa. Pozostaje tylko ją dostarczyć. Ty, $N, musisz to zrobić.$B$BSpółka Gitgeszeft musi mieć jakiś sposób przesyłania wiadomości i lekkich ładunków między swoją siedzibą a działaniami w Szponogłazach. Zapewne jest to niewielki port powietrzny – za mały dla sterowca, ale wystarczający dla fruwającej maszyny. Musisz przeszukać tereny Szponogłazów kontrolowane przez spółkę Gitgeszeft i odnaleźć ten port, jeśli istnieje. Jeśli go znajdziesz, podłóż tam toksynę.$B$BPodłóż ją i uciekaj.', 'Zanieś toksyczny zamgławiacz do portu powietrznego spółki Gitgeszeft, a następnie wróć do aptekarki Zamah.', 'Podłóż toksyczny zamgławiacz', 'Wróć do aptekarki Zamah w Gromowych Urwiskach.', '', '', '', '', 0),
(1102, 'koKR', 'Mściwy los', 'Kairn jest szlachetnym przywódcą, który zjednoczył nasz lud tu, w Gromowych Urwiskach.$b$bJa jednak nie potrafię tak łatwo jak niektórzy wybaczyć tym, którzy wygnali nas z ziem przodków. Mój lud przez dziesięciolecia zamieszkiwał południowe Pustkowia. Ta ziemia była dla nas święta. Lecz przepędziło nas stamtąd wielu wrogów.$b$bMściwy los czeka wiedźmę Charlgę Brzytwoboką, która w Ciernisku Brzytwoskórych gromadzi plugawą armię.$b$bPrzynieś mi serce Brzytwobokiej, a będę mógł umrzeć w spokoju, $n.', 'Przynieś serce Brzytwobokiej Auldowi Kamiennej Iglicy w Gromowych Urwiskach.', '', 'Wróć do Aulda Kamiennej Iglicy w Gromowych Urwiskach.', '', '', '', '', 0),
(1123, 'koKR', '', 'W tej sprawie Rabine Saturna, zarządca Opiekuna Remulosa w Gaju Luny, szuka pomocy w badaniu rozległych pustkowi daleko na zachód od Tanaris i Un\'Goro. Znajdziesz go w Nocnym Azylu, głównej osadzie Gaju Luny.$B$BChcę, byś $gzrozumiał:zrozumiała;, jak ważna jest twoja obecność. Między nocnymi elfami z Darnassus a Kręgiem Cenariona w Gaju Luny narastają napięcia. W sprawach z tamtejszym Kręgiem wznieś się ponad podziały między rasami i sięgnij do mądrości przodków, $N. Powodzenia.', '', '', '', '', '', '', '', 0),
(1130, 'koKR', 'Wieści od Melora', '$N, Melor Kamienne Kopyto słyszał o twoich czynach i wytyczył przed tobą ścieżkę.$B$BJeśli chcesz nią podążyć, udaj się do Gromowych Urwisk i porozmawiaj z Melorem. Znajdziesz go na Wzniesieniu Myśliwego.', 'Porozmawiaj z Melorem Kamiennym Kopytem w Gromowych Urwiskach.', '', '', '', '', '', '', 0),
(1131, 'koKR', 'Stalokłap', 'Czasem polujemy dla pożywienia. Czasem polujemy dla honoru. A czasem polujemy, by zasłużyć na nauki Matki Ziemi.$B$BLecz łowy, na które cię teraz wysyłam, nie są żadnym z nich. Chodzi o zabicie stworzenia, które pozostaje poza błogosławieństwem Matki Ziemi.$B$BHiena Stalokłap grasuje w Tysiącu Filarów, na południe od Pustkowi. To tyran, który gromadzi wokół siebie inne hieny i sieje strach i rozlew krwi wśród spokojniejszych zwierząt.$B$BZnajdź Stalokłapa, $N. Znajdź go i pokonaj.', 'Przynieś żebro Stalokłapa Melorowi Kamiennemu Kopytu w Gromowych Urwiskach.', '', '', '', '', '', '', 0),
(1136, 'koKR', 'Mroźna Paszcza', '$N, nadszedł czas, byś $gwyruszył:wyruszyła; w dalekie krainy. $GJesteś gotów:Jesteś gotowa;.$B$BTeraz zapolujesz na Mroźną Paszczę, yeti z Gór Alterak. Trudno go wytropić, bo jego białe futro zlewa się ze śniegiem jego górskiej siedziby. Rzadko się pokazuje.$B$BLecz pokażę ci, jak zwabić takie stworzenie. Weź ten zwój. Zapisałem na nim, jak wywabić Mroźną Paszczę.$B$BA teraz idź, $N. Droga jest długa i czeka cię wiele wyzwań. Twoje zadanie dobiegnie końca dopiero wtedy, gdy wrócisz z grzywą Mroźnej Paszczy.', 'Przynieś grzywę Mroźnej Paszczy Melorowi Kamiennemu Kopytu w Gromowych Urwiskach.', '', '', '', '', '', '', 0),
(1195, 'koKR', 'Święty płomień', 'Centaury z Galaków w Tysiącu Filarów strzegą artefaktu z czasów stworzenia centaurów.$b$bChcielibyśmy go odzyskać, ale potrzebujemy do tego fiolki wody z jednej z księżycowych studni nocnych elfów.$b$bAby zaczerpnąć wody, musisz najpierw zdobyć jedną z fiolek, które noszą driady w pobliżu Ustronia Raynewood w sercu Jesionowej Kniei. Na zachodnim brzegu Rzeki Falfarren, na południe od głównej drogi, jest księżycowa studnia, przy której napełnisz fiolkę.', 'Przynieś napełnioną grawerowaną fiolkę Zangenowi Kamiennemu Kopytu w Gromowych Urwiskach.', '', 'Wróć do Zangena Kamiennego Kopyta w Gromowych Urwiskach.', '', '', '', '', 0),
(1196, 'koKR', 'Święty płomień', 'Zanieś napełnioną fiolkę Rauowi Biegaczowi Urwisk do Posterunku Wolnego Wiatru w południowo-wschodniej części Tysiąca Filarów. Do Tysiąca Filarów dostaniesz się Wielką Windą na południowym skraju Pustkowi.$b$bNie zdziwiłbym się, gdybyś $gmógł:mogła; pomóc nam jeszcze bardziej.', 'Dostarcz napełnioną grawerowaną fiolkę Rauowi Biegaczowi Urwisk w Posterunku Wolnego Wiatru.', '', '', '', '', '', '', 0),
(1197, 'koKR', 'Święty płomień', 'Dzięki przyniesionej przez ciebie wodzie zdołasz na chwilę przygasić płomień, który strzeże relikwii centaurów. Nie zadziała to jednak na stałe, więc musisz się uwijać.$b$bTurnię Rozszczepionego Kopyta, twierdzę centaurów, znajdziesz na północ stąd. Płomień jest przechowywany w Warowni Rozszczepionego Kopyta, silnie strzeżonej części turni.$b$bUważaj jednak – centaurów z Galaków jest tu mnóstwo i niechętnie oddadzą coś, co jest im tak drogie.', 'Zdobądź rozszczepione kopyto dla Raua Biegacza Urwisk z Posterunku Wolnego Wiatru.', '', 'Wróć do Raua Biegacza Urwisk w Posterunku Wolnego Wiatru w Tysiącu Filarów.', '', '', '', '', 0),
(1205, 'koKR', 'Martwe Bagno', 'Martwe Bagno to prastary krokodyl z Pyłowego Bagniska. I nadszedł jego czas, by umrzeć.$B$BStare kości trzeszczą, gdy wlecze swoje ogromne cielsko przez mokradła, a choć wciąż porusza się z siłą i szybkością młodości, starzejące się ciało dręczy wielkiego ducha, który w nim mieszka – ducha, którego płomień nie słabnie.$B$BLecz teraz żyje w nieustannym, doprowadzającym do szału bólu. Musisz zakończyć życie tego szlachetnego stworzenia, $N. Musisz przynieść Martwemu Bagnu spokój.', 'Przynieś ząb Martwego Bagna Melorowi w Gromowych Urwiskach.', '', '', '', '', '', '', 0),
(1276, 'koKR', 'Czarna tarcza', 'Ach, teraz sobie przypominam! Mosarn to szanowany kowal z Gromowych Urwisk. Wiedziałem, że już gdzieś słyszałem to imię.$b$bW podzięce Krąg Ziemi nagrodził mnie zbroją wykutą przez Mosarna. Bardzo dobra robota.$b$bMoże on powie ci coś więcej o tarczy, którą wykonał.$b$bTo niewiele, ale skoro od Reethe\'a nie wyciągnęliśmy nic przydatnego, nic więcej nie mamy.', 'Pokaż tarczę z czernionego żelaza Mosarnowi w Gromowych Urwiskach.', '', '', '', '', '', '', 0),
(1489, 'koKR', 'Hamuul Runiczny Totem', 'Skorupy, które mi $gprzyniosłeś:przyniosłaś;, noszą skazę, jakiej nigdy dotąd nie widziałem. Jestem pewien, że przyczyną jest woda z oaz, i wyczuwam zamęt, jaki sieją w tej krainie. To tak, jakby ziemia śniła i nie mogła się przebudzić.$B$BŹródłem skazy musi być Zawodząca Pieczara. Lecz zanim tam wyruszysz, porozmawiaj z Hamuulem Runicznym Totemem, starszym druidem. Posłałem mu wieści o tym, co dzieje się na Pustkowiach. Jest mądry i może udzielić ci rady.$B$BZnajdziesz go w Gromowych Urwiskach, na Wzniesieniu Starszych.', 'Porozmawiaj z Hamuulem Runicznym Totemem.', '', '', '', '', '', '', 0),
(1490, 'koKR', 'Nara Dzikogrzywa', 'Wszedłem do krainy snów i śniłem o kulcie druidów, którzy mieszkają w Zawodzącej Pieczarze. Ujrzałem, że niegdyś mieli szlachetne cele, lecz zbłądzili. Są teraz sługami skazy, która przesącza się przez Pustkowia.$B$BJestem stary, a siły mnie opuszczają. Nie mogłem długo przebywać w tej krainie snu i niewiele więcej wiem o skażonych druidach. Lecz Nara jest młoda, a jej duch jest żarliwy. Pozostała w śnie, gdy ja uciekłem.$B$BPorozmawiaj z Narą. Jest w tamtym namiocie.', 'Porozmawiaj z Narą Dzikogrzywą.', '', '', '', '', '', '', 0),
(1532, 'koKR', '', 'Wiatry Kalimdoru pędzą ci na spotkanie, a ty zostaniesz $gzaliczony:zaliczona; do grona naszych najpotężniejszych $gbraci:sióstr;. Jestem dumny, widząc, że tak daleko $gzaszedłeś:zaszłaś; i masz przed sobą tak obiecującą przyszłość.$B$BŻywioł powietrza trudno okiełznać, ale wierzę, że twoje umiejętności przezwyciężą każdą przeszkodę, jaka stanie ci na drodze.$B$BUdaj się na sam południowy kraniec Pustkowi i wejdź do Tysiąca Filarów. Tam, daleko na wschodzie, znajdziesz Prate Chmurowieszczkę. Ona nauczy cię więcej.', '', '', '', '', '', '', '', 0),
(1840, 'koKR', 'Orm Kamienne Kopyto i brutalny hełm', 'Orm Kamienne Kopyto jest wielce szanowany za swój kunszt. On wykona dla ciebie brutalny hełm.$B$BOdszukaj go w Gromowych Urwiskach, przy sadzawce obok wielkiego, centralnego totemu miasta.', 'Porozmawiaj z Ormem Kamiennym Kopytem w Gromowych Urwiskach.', '', '', '', '', '', '', 0),
(1844, 'koKR', 'Róg chimery', 'Wykonam dla ciebie hełm, ale musisz mi pokazać, że jesteś go $ggodzien:godna;.$B$BW południowo-zachodnich zakątkach Gór Szponogłazów leży Zwęglona Dolina. Niegdyś była zielona, lecz teraz jest zbezczeszczona i zasypana popiołem, a stworzenia, które tam pozostały, oszalały z bólu i rozpaczy.$B$BTam cię wysyłam, $N.$B$BMusisz udać się do Zwęglonej Doliny i odnaleźć matriarchę chimer. Zabij ją, uwolnij od cierpienia. Przynieś mi jej galwanizowany róg na dowód, a wykonam dla ciebie hełm.', 'Przynieś galwanizowany róg Ormowi Kamiennemu Kopytu w Gromowych Urwiskach.', '', 'Wróć do Orma Kamiennego Kopyta w Gromowych Urwiskach.', '', '', '', '', 0),
(1845, 'koKR', 'Brutalny hełm', '', '', '', '', '', '', '', '', 0),
(2280, 'koKR', '', 'Gdy znów dotykasz Dysków Norgannona, czujesz mrowienie w dłoni. Tym razem jednak ze środka dysków dobiega dziwny zgrzyt.$B$BTwój plecak nagle staje się cięższy niż przedtem. W środku znajdujesz miniaturową wersję dysków!$B$BBez wątpienia taki przedmiot byłby bezcenny dla kogoś, kogo zajmują dawne dzieje Azeroth. Mędrcy z Gromowych Urwisk to właśnie tacy historycy, znani w całej Hordzie; może oni zrobią z niego dobry użytek.', 'Zanieś miniaturową wersję Dysków Norgannona jednemu z mędrców w Gromowych Urwiskach.', '', '', '', '', '', '', 0),
(2440, 'koKR', '', 'Skupię swoje siły na tych dyskach; w swoim czasie odsłonią przede mną swoje prawdziwe działanie.$B$BCo do ciebie, $N, teraz nagrodzę cię za staranność, z jaką $gzwróciłeś:zwróciłaś; moją uwagę na to znalezisko. Zanieś ten bon Benie Zimowe Kopyto, nauczycielce alchemii w Gromowych Urwiskach. Da ci wyjątkowy przedmiot, który, jak sądzę, przypadnie ci do gustu, i pozwoli wybrać mikstury z moich osobistych zapasów.$B$BWróć do mnie niebawem, bo czuję, że w związku z tym znaleziskiem czeka nas jeszcze wiele pracy.', 'Zanieś bon z nagrodą Benie Zimowe Kopyto w Gromowych Urwiskach.', '', '', '', '', '', '', 0),
(2860, 'koKR', '', '$n, nauczyłem cię wszystkiego, czego mogłem. Pozostał jednak jeszcze jeden wykrój zbroi z dzikiej skóry. Nie będę kazał ci się niepotrzebnie trudzić, by go zdobyć; w pełni na niego $gzasłużyłeś:zasłużyłaś;, i to z nawiązką. Tym wykrojem nie mogę się jednak z tobą swobodnie podzielić.$B$BTo moja nauczycielka, ta, która wprowadził mnie w rzemiosło, musi cię nagrodzić. Zanieś ten list Unie; uczy kaletnictwa w Gromowych Urwiskach. Pokaż jej list i pozwól, by uznała cię za $grównego:równą; sobie, tak jak ja.', 'Oddaj list Jangdora Unie, mistrzyni kaletnictwa w Gromowych Urwiskach.', '', '', '', '', '', '', 0),
(2965, 'koKR', '', 'Ach, $n, to szczęśliwy traf, że znów do mnie przychodzisz. Twoje odkrycia na wykopaliskach w Uldamanie dały nam, mędrcom, wiele do omówienia. Właśnie o nich rozmawiałem z jedną z druidek, Narą Dzikogrzywą, gdy przyszło mi do głowy, że jej dawne wyprawy mogą mieć wielkie znaczenie dla naszego następnego kroku.$B$BChciałbym, żebyś $gporozmawiał:porozmawiała; z nią o jej podróżach do Doliny Strażników na pustyni Tanaris. Czeka na ciebie na Wzniesieniu Starszych.', 'Porozmawiaj z Narą Dzikogrzywą na Wzniesieniu Starszych w Gromowych Urwiskach.', '', '', '', '', '', '', 0),
(2966, 'koKR', '', 'Mędrzec Poszukiwacz Prawdy i ja chcielibyśmy, żebyś $gzaniósł:zaniosła; znalezione przez ciebie miniaturowe dyski do zapieczętowanych wrót Uldum. Nie... nie jesteśmy pewni, co się stanie, gdy to zrobisz.$B$BTak, brzmi to ryzykownie, przyznajemy. Może jednak nic się nie wydarzy. Być może trzeba będzie użyć dysków na czymś. Być może wrota otworzą się, gdy będziesz mieć dyski przy sobie. Bądź $gotwarty:otwarta; na każdą próbę i $ggotów:gotowa; na wszystko.$B$BDowiedz się, czego zdołasz, i wróć do mnie. Będziemy mieli wiele do omówienia.', '', '', '', '', '', '', '', 0),
(2967, 'koKR', 'Powrót do Gromowych Urwisk', 'Ponownie uzyskujesz dostęp do piedestału; platynowe dyski nagle znów pojawiają się w twoim plecaku.$B$BZ wiedzą przekazaną przez kamiennego obserwatora i z dyskami z powrotem w twoim posiadaniu nadszedł czas, by wrócić do Gromowych Urwisk i powiadomić Narę Dzikogrzywą o swoim odkryciu.', 'Porozmawiaj z Narą Dzikogrzywą w Gromowych Urwiskach.', '', '', '', '', '', '', 0),
(2968, 'koKR', '', 'Cóż, $n... wygląda na to, że utknęliśmy w martwym punkcie. Wiemy, czego potrzebujemy – Płyt Uldum – ale nie mamy pojęcia, gdzie mogą być. Zbadamy tę sprawę, a potem opracujemy solidny plan działania. Mam kilka pomysłów, od czego zacząć poszukiwania; mocno wierzę, że wkrótce znów poprosimy cię o dołączenie do naszych starań o odkrycie prawdy.$B$BTrzeba o tym powiadomić mędrca Poszukiwacza Prawdy, $n; bez wątpienia chce też osobiście podziękować ci za to, że po raz kolejny $godpowiedziałeś:odpowiedziałaś; na wezwanie.', 'Porozmawiaj z mędrcem Poszukiwaczem Prawdy w Gromowych Urwiskach.', '', '', '', '', '', '', 0),
(3369, 'koKR', '', 'Ten odłamek kryje wielkie sekrety; to czysta esencja Szmaragdowego Snu. Jednak to, co w nim widzę, nie jest snem; taką wizję nazwałoby się koszmarem.$B$BNie chcę cię niepokoić, $N, ale sądzę, że najlepiej będzie, jeśli jak najszybciej oddasz ten odłamek w ręce mądrego druida.$B$BMusisz udać się do Hamuula Runicznego Totemu na Wzniesieniu Starszych. Udaj się do Gromowych Urwisk. Więcej nie mogę powiedzieć.', 'Zanieś odłamek koszmaru Hamuulowi Runicznemu Totemowi na Wzniesieniu Starszych.', '', '', '', '', '', '', 0),
(3518, 'koKR', 'Przesyłka dla Magaty', 'Pierwsza tablica trafi do taurenki... niejakiej Magaty. Zasiada wśród starszyzny w Gromowych Urwiskach i jest jedną z orędowniczek sojuszu taurenów z Porzuconymi. Bardziej niż ktokolwiek ze starszyzny wierzy, że taureni i ich obyczaje mogą pomóc Porzuconym odnaleźć drogę powrotną do człowieczeństwa.$B$BZanieś jej tablicę Beth\'Amara. Ta tablica może być ogniwem, którego potrzebuje, by znaleźć sposób na pomoc Porzuconym... a przynajmniej tak twierdzi.', 'Zanieś tablicę Beth\'Amara Magacie w Gromowych Urwiskach.', '', '', '', '', '', '', 0),
(3562, 'koKR', 'Zapłata Magaty dla Jedigi', 'Zanieś ten liścik Jedidze. Powiedz jej, że zapłata będzie tu na nią czekać, gdy wróci. I powiedz, że jestem zadowolona z jej pracy.$B$BRuszaj szybko, $N. Przekaż swojej pani, że będę na nią tu czekać.', 'Dostarcz liścik Magaty Jedidze w Aszarze.', '', '', '', '', '', '', 0),
(3581, 'koKR', '', 'Wyobraź sobie, że pędzisz przez równiny, przez lasy i ponad górami, z wiatrem na twarzy... Przemierzasz nieznane ziemie, zachwyca cię droga przed tobą, a twoje przeznaczenie czeka tuż za horyzontem.$B$BPamiętaj zawsze, że na kopytach można osiągnąć wiele; jako tauren otrzymasz szybkość Biegu przez równiny. Nie ma granic odległości, jakie możesz pokonać.', 'Porozmawiaj ponownie z Saernem Dumnym Biegiem, aby nauczyć się umiejętności Bieg przez równiny.', '', '', '', '', '', '', 0),
(3761, 'koKR', '', 'Podobno ziemia z Krateru Un\'Goro jest nasycona silnymi magicznymi właściwościami. Krąg Cenariona chce zbadać tę ziemię w dużych ilościach; wyrusz w dzicz Un\'Goro i zdobądź jej tyle, ile potrzeba do dalszych badań.$B$BTę żyzną ziemię znajdziesz tu i ówdzie w kopczykach, a niektóre bestie mogą mieć przy sobie próbki nadające się do użytku. Zanieś je wszystkie na zewnątrz do Ghedego – wystarczy wypatrywać kopców ziemi i taurena, który wykrzykuje rozkazy. Ma dobre intencje, tylko lepiej go nie rozdrażniać!', 'Przynieś 20 próbek ziemi z Un\'Goro Ghedemu na Wzniesieniu Starszych w Gromowych Urwiskach.', '', 'Wróć do Ghedego przy Ujęciu Wody Dzikogrzywych w Mulgorze.', '', '', '', '', 0),
(3782, 'koKR', '', 'W tak zwanej sakiewce wiecznej zieleni hodujemy nasiona tharlendris w ziemi z Krateru Un\'Goro. Z nasion tych wyrastają rozmaite, przypadkowe zioła o silnych właściwościach. Jednym z nich jest jutroziarno, tajemnicze zioło, o którym niewiele wiemy; bardzo liczę na to, że zgłębię tę tajemnicę dla Kręgu.$B$BZanieś ten bon mojej córce Bashanie, a da ci trochę nasion, żebyś $gmógł:mogła; nam pomóc. Jeśli ci się skończą, będziesz $gmusiał:musiała; dokupić więcej u niej.', 'Zanieś bon na nasiona Bashanie Runicznemu Totemowi w Gromowych Urwiskach.', '', '', '', '', '', '', 0),
(3786, 'koKR', '', 'Oto sakiewka wiecznej zieleni, której będziesz potrzebować do nasion tharlendris. Musisz też mieć przy sobie próbki ziemi z Un\'Goro, które posłużą nasionom za nawóz. Gdy będziesz mieć wszystko, po prostu użyj sakiewki – ona zajmie się resztą.$B$BGdy zbierzesz dość jutroziarna, przynieś je do mnie, tutaj, na Wzniesienie Starszych. I proszę, nie niepokój arcydruida; będzie bardzo zajęty badaniami, a do tego ma mnóstwo innych zmartwień!', 'Użyj sakiewki wiecznej zieleni z paczką nasion tharlendris i dwiema próbkami ziemi z Un\'Goro, aby spróbować wyhodować jutroziarno.$B$BPrzynieś 10 sztuk jutroziarna Bashanie Runicznemu Totemowi w Gromowych Urwiskach.', '', 'Wróć do Bashany Runicznego Totemu na Złotych Równinach w Mulgorze.', '', '', '', '', 0),
(3804, 'koKR', 'Jutroziarno dla Gromowych Urwisk', '', '', '', 'Wróć do Bashany Runicznego Totemu na Mrocznym Pustkowiu.', '', '', '', '', 0),
(4883, 'koKR', 'Strzeżone tajemnice', 'Choć wiem wiele o sowostworach, które $gpokonałeś:pokonałaś; w Zimozdroju, niewiele wiem o magii, którą władają. Znam jednak kogoś, kto zdoła zbadać ten naszyjnik i najpewniej powie ci, czym jest.$B$BNara Dzikogrzywa z Gromowych Urwisk jest znawczynią tej dziedziny; odwiedź ją. Powodzenia, $N.', 'Zanieś naszyjnik z niebieskich piór Narze Dzikogrzywej.', '', '', '', '', '', '', 0),
(4987, 'koKR', '', 'Martwa dłoń taurena druida ściska zaskakująco zdrową z wyglądu dębową gałąź. Przy bliższych oględzinach widać na korze wyryte glify o druidzkim charakterze.$B$BGdy chwytasz gałąź, czujesz, że jest ciepła w dotyku, cieplejsza, niż powinna. W twoim umyśle pojawia się obraz Gromowych Urwisk w Mulgorze – a konkretnie Wzniesienia Starszych – a na końcu języka masz słowa „Krąg Cenariona”. Wygląda na to, że w gałęzi zaklęto wskazówkę, dokąd należy ją zanieść.', 'Sądząc po magii zaklętej w dębowej gałęzi z glifami, dostarczenie jej do Kręgu Cenariona w Gromowych Urwiskach było kolejnym krokiem, do którego dążył tauren druid. Poproś o pomoc któregoś z tamtejszych druidów.', '', '', '', '', '', '', 0),
(5062, 'koKR', 'Święty ogień', 'Arikara to zabójcza istota, z którą trzeba szybko się rozprawić. Aby ją wytropić, musisz rozpalić święty ogień życia – to przywoła Arikarę.$B$BIdź teraz i zbierz rzadką agawę zapalającą. Gdy zbierzesz jej dość, zasięgnij rady Magaty Ponurego Totemu na Wzniesieniu Starszych w Gromowych Urwiskach. To potężna szamanka, która potrafi zakląć agawę tak, by powstał proszek, który rozpali ogień.$B$BUdaj się na północny wschód, do Wrzącej Sadzawki, i zbierz agawę zapalającą.', 'Zbierz 10 pęczków agawy zapalającej, a następnie zasięgnij rady Magaty Ponurego Totemu na Wzniesieniu Starszych w Gromowych Urwiskach.', '', 'Wróć do Magaty Ponurego Totemu w Gromowych Urwiskach.', '', '', '', '', 0),
(5088, 'koKR', 'Arikara', 'Zanieś ten oczyszczony i uszlachetniony proszek zapalający do Tysiąca Filarów i rzuć go w święty ogień życia. Znajdziesz go na Szczycie Mrocznej Chmury, na odosobnionym filarze, gdzie grzebią swoich zmarłych.$B$BZaklęcie, które wplotłam w proszek zapalający, przywoła do ciebie Arikarę, $N.$B$BObawiam się, że może czyhać na Kairna Krwawego Kopyta; zbyt wiele z tradycji taurenów się zmieniło i boję się, że to rozgniewało Arikarę. Działaj szybko, zanim wszystko przepadnie, $N!', 'Zabij Arikarę. Na dowód swojego czynu zanieś jej szczątki i proszek zapalający Motedze Ognistej Grzywie w Posterunku Białego Zasięgu.', 'Rozpal Święty Ogień Życia', 'Wróć do Motegi Ognistej Grzywy w Posterunku Białego Zasięgu w Tysiącu Filarów.', '', '', '', '', 0),
(5095, 'koKR', '', 'Bohaterowie królestwa, posłuchajcie mnie – Horda wzywa was do szybkiego działania!$B$BOgłoszono wezwanie do broni dla wszystkich zdolnych do walki, by chwycili za oręż przeciw Pladze! Krążą plotki o nowych zagrożeniach, które powstają z ruin Wschodnich Królestw. Czają się na wschód od Podmiasta, w północnych rubieżach krain znanych dziś jako Plagowiska!$B$BBohaterowie królestwa – odszukajcie najwyższego egzekutora Derringtona, który rozbił obóz przy Barykadzie, na wschód od Gajów Tirisfalskich!', 'Odszukaj najwyższego egzekutora Derringtona. Jego obóz znajduje się przy Barykadzie, na wschód od Gajów Tirisfalskich i Podmiasta.', '', '', '', '', '', '', 0),
(5722, 'koKR', 'W poszukiwaniu zaginionej sakwy', 'Nie tylko troggi zainteresowały Magatę w Rozpadlinie Wściekłego Ognia. Doszły ją słuchy, że jeden z jej sług, niejaki Maur Ponury Totem, znalazł w Rozpadlinie coś osobliwego, ale nie zdołał się stamtąd wydostać, by jej to pokazać. Chciałaby, żeby odnaleziono ciało Maura – o ile jeszcze istnieje – i wszelkie ślady tego, co znalazł, próbując porozumieć się z troggami.$B$BZanieś Magacie wszystko, co wyda ci się interesujące, a jestem pewien, że hojnie cię wynagrodzi.$B$BPowtarzam: szukaj Rozpadliny w najmroczniejszych zakątkach Orgrimmaru.', 'Odszukaj w Rozpadlinie Wściekłego Ognia zwłoki Maura Ponurego Totemu i przeszukaj je w poszukiwaniu interesujących przedmiotów.', '', '', '', '', '', '', 0),
(5723, 'koKR', 'Próba sił wroga', 'Pod miastem Orgrimmar, z głębi wypełnionych lawą tuneli, na powierzchnię zaczęły wychodzić krępe stworzenia zwane troggami. W swojej niezmiennej dobroci Magata próbowała zawrzeć z nimi pokój, lecz one zwróciły się przeciwko jej wysłannikom i ich zabiły. Magata nie pozwoli, by tak traktowano lud taurenów, i uważa teraz te stworzenia za zagrożenie dla całej Hordy.$B$BProsi cię, byś $gpołożył:położyła; kres zagrożeniu ze strony troggów, zanim zaleją Hordę od spodu. Odnajdź Rozpadlinę Wściekłego Ognia i zniszcz je wszystkie.', 'Odszukaj w Orgrimmarze Rozpadlinę Wściekłego Ognia, zabij 8 troggów Wściekłego Ognia i 8 szamanów Wściekłego Ognia, a następnie wróć do Rahauro w Gromowych Urwiskach.', '', 'Wróć do Rahauro na Wzniesieniu Starszych w Gromowych Urwiskach.', '', '', '', '', 0),
(5724, 'koKR', 'Zwrot zaginionej sakwy', 'Pod ciałem taurena znajdujesz sakwę. Wciąż ściska ją mocno w ramionach, jakby próbował ją chronić, gdy atakowały go troggi.$B$BWyjmujesz sakwę z jego żelaznego uścisku, chowasz ją do swojego ekwipunku i szykujesz się do wyjścia z tuneli i powrotu do Rahauro w Gromowych Urwiskach.', 'Zanieś sakwę Ponurego Totemu Rahauro w Gromowych Urwiskach.', '', '', '', '', '', '', 0),
(5922, 'koKR', '', 'Wszyscy druidzi, zarówno taureni, jak i nocne elfy, są mile widziani w świętej krainie Gaju Luny. Opiekun Remulos – strażnik Gaju Luny – czuwa nad wszystkimi druidami, którzy tam zapadają w sen. Skoro poznajesz już drogę Pazura, nauczę cię czaru, który pozwoli ci się tam przenieść. Rzucaj go zawsze, gdy szukasz wiedzy lub ukojenia Gaju Luny.$B$BNa pierwszą lekcję udaj się do Gaju Luny i porozmawiaj z Dendrite\'em Gwiezdnym Płomieniem w Nocnym Azylu o ścieżce, na którą $gwkroczyłeś:wkroczyłaś;. Powodzenia, $gmłody druidzie:młoda druidko;.', '', '', '', '', '', '', '', 0),
(5932, 'koKR', 'Powrót do Gromowych Urwisk', 'Nadszedł czas, by nasze drogi się rozeszły, $gmłody druidzie:młoda druidko;, bo stosowanie twoich lekcji prowadzi cię z powrotem do tego, kto cię do mnie przysłał. Choć taurenów uważa się za młodych na drodze Cenariusa, Turak Runiczny Totem kroczy w pełnej równowadze z naturą. Słuchaj jego wskazówek, a wkrótce ukończysz pierwsze lekcje swojej roli obrońcy równowagi.$B$BIdź już, $gmłody druidzie:młoda druidko;. Jeszcze się spotkamy.', 'Wróć do Gromowych Urwisk i porozmawiaj z Turakiem Runicznym Totemem na Wzniesieniu Starszych.', '', '', '', '', '', '', 0),
(6002, 'koKR', '', 'Na ziemiach na zachód od Taurajo na Pustkowiach – tuż przed granicą z Mulgorem – leży Kamień lunozwierzy. Lunozwierze to niezwykłe bestie, nie pochodzą z tych stron. Księżycowy Szpon, obrońca kamienia, stanie z tobą do walki, gdy użyjesz na kamieniu cenariońskiego pyłu księżycowego. Księżycowy Szpon skrywa w sobie siłę, którą ty, jako $gjeden:jedna; z Pazura, musisz wykorzystać.$B$B$GZasłużyłeś:Zasłużyłaś; na prawo użycia tego cenariońskiego pyłu księżycowego, $N... teraz pokaż mi, że $gzasłużyłeś:zasłużyłaś; też na siłę ciała i siłę serca, których potrzebuje druid!', 'Użyj cenariońskiego pyłu księżycowego na Kamieniu lunozwierzy między Mulgorem a Pustkowiami, aby przywołać Księżycowego Szpona. Następnie zmierz się z nim i zdobądź siłę ciała i serca, którą w sobie nosi.$B$BGdy skończysz, porozmawiaj z Turakiem Runicznym Totemem w Gromowych Urwiskach.', '', 'Wróć do Turaka Runicznego Totemu w Gromowych Urwiskach.', '', '', '', '', 0),
(6130, 'koKR', '', '$GPoznałeś:Poznałaś;, co znaczy leczyć zatrucia bez pomocy duchowej mocy. Pamiętaj, co muszą znosić inni w walce z truciznami, gdy wkrótce obejmiesz swoją nową władzę nad nimi.$B$BWróć teraz do Turaka Runicznego Totemu w Gromowych Urwiskach, $N. Bez wątpienia ma dla ciebie bardzo ważny czar, skoro $guczeń zrozumiał daną mu:uczennica zrozumiała daną jej; lekcję.$B$BBywaj, $gmłody druidzie:młoda druidko;. Jeszcze porozmawiamy.', 'Wróć do Turaka Runicznego Totemu na Wzniesieniu Starszych w Gromowych Urwiskach.', '', '', '', '', '', '', 0),
(6362, 'koKR', 'Lot do Gromowych Urwisk', 'Za niewielką opłatą dam ci wiwernę do Gromowych Urwisk. Nie ma szybszej drogi do miasta!$B$BJeśli ci to odpowiada, porozmawiaj ze mną znowu, gdy będziesz $ggotów:gotowa; do drogi.$B$BJeśli niesiesz te skóry Ahanu, to chyba znajdziesz go w Zbrojowni Hewy, u podnóża wieży wiwern w Gromowych Urwiskach. Dokładnie tam wylądujesz!', 'Wykup u mistrza wiwern Devraka lot wiwerną do Gromowych Urwisk, a potem zanieś wiązkę skór Ahanu w Gromowych Urwiskach.', '', '', '', '', '', '', 0),
(6363, 'koKR', 'Tal, mistrz wiwern', 'Przygotowałem wyroby skórzane, które Jahan ma sprzedawać na Rozdrożu. Zaniesiesz mu je?$B$BJeśli już $gbyłeś:byłaś; na Rozdrożu i $grozmawiałeś:rozmawiałaś; z tamtejszym mistrzem wiwern, możesz polecieć do niego jedną z naszych wiwern z Gromowych Urwisk.$B$BZanieś wyroby skórzane Talowi, naszemu mistrzowi wiwern w Gromowych Urwiskach, i porozmawiaj z nim o transporcie na Rozdroże.', 'Zanieś wyroby skórzane Ahanu Talowi w Gromowych Urwiskach.', '', '', '', '', '', '', 0),
(6364, 'koKR', 'Powrót do Jahana', 'Aby polecieć do jakiejś osady, musisz już wcześniej tam być i porozmawiać z tamtejszym mistrzem wiwern. $GByłeś:Byłaś; na Rozdrożu i $grozmawiałeś:rozmawiałaś; z ich mistrzem wiwern, Devrakiem, więc za niewielką opłatą możesz polecieć stąd wiwerną prosto do niego.$B$BPorozmawiaj ze mną znowu, gdy będziesz $ggotów:gotowa;. Na Rozdrożu dostarczysz wyroby skórzane Jahanowi Jastrzębiemu Skrzydłu.', 'Wykup u mistrza wiwern Tala lot wiwerną na Rozdroże, a potem zanieś wyroby skórzane Ahanu Jahanowi Jastrzębiemu Skrzydłu.', '', '', '', '', '', '', 0),
(6561, 'koKR', '', 'Opuściły mnie siły. Potrzebuję twojej pomocy!$b$bDawno temu stała tu wielka świątynia Eluny. Ale nieszczęście doprowadziło ją do ruiny, gdy spaczenie jednego z Przedwiecznych Bogów przesączyło się spod ziemi i skaziło świętą księżycową studnię.$b$bZ wód wynurzył się Aku\'mai, sługa Przedwiecznego.$b$bKultyści Młota Zmierzchu sprzymierzyli się z nagami, by zająć te tereny. Kultyści pod wodzą Kelrisa składają niewinnych w ofierze Aku\'mai, by zyskać moc.$b$bZabij Kelrisa i zanieś jego głowę Bashanie w Gromowych Urwiskach, $N. Proszę.', 'Zanieś głowę Władcy Zmierzchu Kelrisa Bashanie Runicznemu Totemowi w Gromowych Urwiskach.', '', 'Wróć do Bashany Runicznego Totemu na Wzniesieniu Starszych w Gromowych Urwiskach.', '', '', '', '', 0),
(7820, 'koKR', '', '', '', '', 'Wróć do Rumstaga Dumnego Kroku na Mrocznym Pustkowiu.', '', '', '', '', 0),
(7821, 'koKR', '', '', '', '', 'Wróć do Rumstaga Dumnego Kroku na Mrocznym Pustkowiu.', '', '', '', '', 0),
(7822, 'koKR', '', '', '', '', 'Wróć do Rumstaga Dumnego Kroku na Mrocznym Pustkowiu.', '', '', '', '', 0),
(7823, 'koKR', '', '', '', '', 'Wróć do Rumstaga Dumnego Kroku na Mrocznym Pustkowiu.', '', '', '', '', 0),
(7825, 'koKR', '', '', '', '', 'Wróć do Rumstaga Dumnego Kroku na Mrocznym Pustkowiu.', '', '', '', '', 0),
(8360, 'koKR', '', '', 'Użyj emotki tańca przy karczmarce Pali, a w zamian otrzymasz marcepan z Gromowych Urwisk!', '', 'Wróć do karczmarki Pali w Gromowych Urwiskach.', 'Zatańcz dla karczmarki Pali', '', '', '', 0),
(8861, 'koKR', '', 'Gromowe Urwiska świętują Nowy Rok! Przez cały dzień można tam dostać darmową gorzałę, a w nocy będzie pokaz fajerwerków!$B$BPowinno być całkiem fajnie... ale w Łupieżczej Zatoce też jest dziś impreza; założę się, że będzie jeszcze lepsza!$B$BW każdym razie karczmarka Pala z Gromowych Urwisk potrzebuje zapasów jadła od Wędzonych Pastwisk, żeby wykarmić wszystkich gości. Zrobisz mi przysługę i je dostarczysz?$B$BDzięki, $N! Karczmarka Pala jest w karczmie przy moście na Wzniesienie Myśliwego.', 'Zanieś zapasy od Wędzonych Pastwisk karczmarce Pali w Gromowych Urwiskach.', '', '', '', '', '', '', 0),
(11204, 'koKR', 'Powrót do Kroga', 'Mam nadzieję, że choć trochę ci pomogłem, i przykro mi, że nie mogę powiedzieć nic więcej. Moi uczniowie i ja wykuwamy tyle broni i pancerzy, że niemal nie sposób zapamiętać szczegółów pojedynczej sztuki.$B$BNie tylko wyposażamy wojowników broniących ziem taurenów – Ponure Totemy szczególnie upodobały sobie moje wyroby. Doświadczony wojownik pozna dobrą robotę, gdy ją zobaczy.', 'Porozmawiaj z Krogiem w Paprotni.', '', '', '', '', '', '', 0),
(13986, 'koKR', 'Ranna towarzyszka', 'Walki są tu ciężkie, $N, jak zapewne wiesz. Trzymamy się, ale nie wszyscy wyszli z tego bez szwanku.$b$bAponi Jasna Grzywa, wojowniczka z naszego oddziału, zachorowała od zakażonej rany na ramieniu. Zabrano ją z powrotem do Gromowych Urwisk, by wróciła do zdrowia. W zamieszaniu zostawiła jednak tu, na froncie, swoją tarczę – $gmógłbyś:mogłabyś; zanieść jej ją razem z naszymi życzeniami powrotu do zdrowia? Brakuje nam tu jej uśmiechu.$b$bZnajdziesz ją na Wzniesieniu Starszych w Urwiskach.', 'Zanieś zniszczoną plemienną tarczę Aponi Jasnej Grzywie na Wzniesieniu Starszych w Gromowych Urwiskach.', '', 'Wróć do Aponi Jasnej Grzywy w Mulgorze.', '', '', '', '', 0),
(24614, 'koKR', 'Podarunek dla wielkiego wodza', 'Chcesz zrobić uroczą bransoletkę z talizmanami dla wielkiego wodza? Na pewno byłby zachwycony.$B$BMasz już zestaw kolekcjonera uroczych talizmanów?', 'Wręcz uroczą bransoletkę z talizmanami Kairnowi Krwawemu Kopytu w Gromowych Urwiskach.', '', '', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(31, 'koKR', 'Bardzo imponujące, $N. Twoi przodkowie byliby dumni z twoich postępów! Jesteś $ggotów:gotowa;, by poznać postać wodną, a nauczenie cię jej sprawi mi przyjemność.$B$BW uznaniu twoich osiągnięć podczas obu prób daję ci też ten przedmiot. Mam nadzieję, że będzie mile widzianym uzupełnieniem ekwipunku obrońcy natury i strażnika równowagi.', 0),
(264, 'koKR', 'Kładziesz bezwartościowy wisior na grobie, a kamień w oprawie wyraźnie matowieje.$b$bWstając do odejścia, spoglądasz na wisior: leży bez życia na dłoniach płaskorzeźby wyrytej w wieku trumny. Twoje myśli przerywa ostry, chłodny powiew, który przemyka przez Grobowisko. Przez chwilę wokół panuje zupełna cisza.', 0),
(744, 'koKR', 'Dziękuję za pomoc, $N.$b$bMoja rola w ceremonii brata jest niemal wypełniona. Obowiązek wymaga ode mnie już tylko wręczenia mu pióropusza i bycia świadkiem ceremonii.', 0),
(768, 'koKR', 'Ach, to bardzo ładne kawałki. Wyjdą z nich porządne wyroby ze skóry.$B$BProszę, $N. Weź to w zamian...', 0),
(769, 'koKR', 'Ach, dobrze. Dziękuję, $N. Serce rośnie mi z dumy, gdy widzę młodych, których zajmuje rzemiosło kaletnicze.', 0),
(853, 'koKR', 'Ach, zarodniki z Pustkowi, które zbierał Helbrim. Poprosił cię o pomoc w ich dostarczeniu? Dobrze.$B$BA emulsja wciąż zachowała moc, więc nie $gzmarnowałeś:zmarnowałaś; ani chwili. Dobra robota, $N.', 0),
(860, 'koKR', 'Chcesz polować na Pustkowiach?$b$bTwoje oczy są pełne zapału i młode. Jeszcze nie zmrużyły się od tropienia zwierzyny na suchych równinach tej krainy.$b$bAle nie martw się. Zahartujemy twoje ciało i umysł. I nauczymy cię, że łowy to coś więcej niż odnalezienie i zabicie zdobyczy.$b$bPrzygotuj się. Twoja wędrówka się zaczyna. Teraz.', 0),
(886, 'koKR', 'Moi bracia z Gromowych Urwisk mądrze uczynili, przysyłając cię tutaj, $N. Tajemnicy Pustkowi nie zdołam bowiem rozwikłać sam.$B$BMiejmy nadzieję, że z twoją pomocą znajdziemy odpowiedzi na nasze pytania.', 0),
(914, 'koKR', 'Udało ci się, $N. $GZabiłeś:Zabiłaś; przywódców Druidów Kła. Moje sny są wolne od ich nikczemnych twarzy, a ty $gpomogłeś:pomogłaś; ocalić Pustkowia przed przeklętą przyszłością.$b$bDziękuję ci, $N. Dziękuję w imieniu swoim, druidów z Gromowych Urwisk i tej ziemi.', 0),
(962, 'koKR', 'Ach, wspaniałe okazy. Dobrze się $gspisałeś:spisałaś;, $N.', 0),
(1049, 'koKR', 'Kompendium Poległych! Zaczynałem się już zastanawiać, czy ta księga w ogóle istnieje!$b$bDobrze $gsłużyłeś:służyłaś; taurenom z Gromowych Urwisk, $N. Twoje oddanie nie zostanie zapomniane.', 0),
(1063, 'koKR', 'Witaj. Przychodzisz po radę?', 0),
(1064, 'koKR', 'Magata zapowiedziała twoje przybycie, $N. Choć moje serce już nie bije, wciąż czuję smutek z powodu duchów Szponogłazów.$b$bPorzuceni chętnie udzielą takiej pomocy, jakiej tylko zdołamy.', 0),
(1065, 'koKR', 'Liścik od Zamah? Musi mieć pilne potrzeby, skoro śle wiadomość z tak daleka. Zobaczmy, co pisze...$b$bAch, wspaniale! Dokładnie wiem, co zrobić!', 0),
(1066, 'koKR', 'Bardzo dobrze! Ufam, że Syndykat nie sprawił ci wielkich kłopotów?$B$BJak wspomniałem, krew niewinnych niełatwo zdobyć. Mamy szczęście, że magowie cienia z Syndykatu odwalili za nas najtrudniejszą robotę.$B$BA teraz chwileczkę, przygotuję swoją miksturę...', 0),
(1067, 'koKR', 'Toksyna od aptekarza Lydona? Bardzo dobrze. Jeśli dobrze znam Lydona, ta toksyna będzie bardzo skuteczna przeciw spółce Gitgeszeft...', 0),
(1086, 'koKR', '$GZnalazłeś:Znalazłaś; port? Dobra robota, $N! Jestem pewna, że gobliny były wielce zaskoczone twoją przesyłką! Miejmy nadzieję, że toksyna trafi do ich siedziby.$B$BDobrze $gprzysłużyłeś:przysłużyłaś; się swojemu ludowi i radzę ci zignorować wszelkie wyrzuty sumienia z powodu otrucia spółki Gitgeszeft. Zasługują na znacznie gorszy los.$B$BA jeśli istnieje choć okruch mądrości, którą Porzuceni mogą przekazać sojusznikom, to jest nim ten:$B$BNie unikaj mrocznych ścieżek... jeśli prowadzą do zwycięstwa.', 0),
(1102, 'koKR', 'Widzę, że podłe plemię z Cierniska Brzytwoskórych zna teraz ból mojego ludu. Dobrze tak tym plugawym bestiom.$b$bWygnanie kogoś ze świętej ziemi to grzech godny najsurowszej zemsty.$b$bDziękuję ci, $N, że $gpomogłeś:pomogłaś; mi w mojej niedoli.', 0),
(1123, 'koKR', 'Jestem Rabine Saturna i w imieniu Opiekuna Remulosa oraz wszystkich mieszkańców tego świętego gaju witam cię.$B$BCenię twoje zainteresowanie i gotowość, by pomóc Kręgowi Cenariona. Taureni okazali niezwykłe przywiązanie do nauk Cenariusa i dzięki nim Horda jest mile widziana w bezpiecznym schronieniu tego gaju. Ochrona Azeroth to nasz wspólny cel.$B$BJesteś tu wśród przyjaciół, $N.', 0),
(1130, 'koKR', 'A więc $gprzybyłeś:przybyłaś;, $N. Czy $gjesteś gotów:jesteś gotowa; wyruszyć w dalekie krainy?$B$BJeśli tak, słuchaj uważnie...', 0),
(1131, 'koKR', 'Pokonując Stalokłapa, $goczyściłeś:oczyściłaś; Tysiąc Filarów z okropnej skazy.$b$bI to, $N, jest twoja dzisiejsza lekcja.', 0),
(1136, 'koKR', 'Aby znaleźć i pokonać Mroźną Paszczę, trzeba było zarówno siły, jak i sprytu, $N. Masz jedno i drugie.$b$bTwoja ścieżka zaprowadziła cię do dolin Tysiąca Filarów i w wysokie góry Alterak. Pewnego dnia poprowadzi cię przez wszystkie ziemie Matki Ziemi, bo taka jest droga łowcy.', 0),
(1195, 'koKR', 'Bardzo dobrze. To w pełni zaspokoi prośbę Raua. Czy $gmógłbyś:mogłabyś; mu to zanieść? Może spodoba ci się trochę czasu spędzonego w Filarach.', 0),
(1196, 'koKR', 'Hm, tak, ta fiolka wody doskonale posłuży naszym celom. Ze względu na wspólne pochodzenie driad i centaurów woda z księżycowych studni pozwoli nam przełamać ochronę wiecznego płomienia, który otacza relikwię centaurów.', 0),
(1197, 'koKR', 'Wyczuwam dziwną energię bijącą od Kopyta... Nie wątpię, że badając je, odkryjemy zaskakujące nowe fakty o centaurach.$B$BDziękuję ci, $N. Teraz muszę zacząć zgłębiać tajemnice, które mi $gprzyniosłeś:przyniosłaś;.', 0),
(1205, 'koKR', 'Bardzo dobrze, $N.$b$bJestem pewien, że łowy nie były łatwe, ale dobrze wiedzieć, że ból tej bestii wreszcie się skończył.', 0),
(1276, 'koKR', 'Tak, masz całkowitą rację. To tarcza mojej roboty.$b$bObawiam się jednak, że niewiele więcej mogę ci powiedzieć, $N. Wykonuję tyle różnych tarcz i zbroi, że nie jestem w stanie spamiętać ich wszystkich.', 0),
(1489, 'koKR', 'Witaj, $N. Jesteś tu mile $gwidziany:widziana;, a radzę ci zebrać wszystkie siły. Zadanie, które przed tobą stawiamy... jest bowiem groźne.', 0),
(1490, 'koKR', 'Tak, to prawda. Wiem o druidach z Zawodzącej Pieczary. Widziałam ich wypaczone, pokryte łuską twarze. Znam ich zbrodnie i znam ich plany.$b$bMusisz ich powstrzymać, $N.', 0),
(1523, 'koKR', 'Hmmm, przysłał cię do mnie Narm, tak?$B$BCóż, Narmowi zawsze można było ufać, a zatem musisz być $ggotów:gotowa;, by przystąpić do kolejnej sapty – sapty ognia.$B$BJuż widzę to w twoich oczach: żar, pragnienie. $GZakosztowałeś:Zakosztowałaś; mocy i teraz $gjesteś gotów:jesteś gotowa; na więcej. Cierpliwości, $N. Pamiętaj, czego nauczyła cię ziemia. Moc i zniszczenie przyjdą łatwo, ale wciąż musisz wiedzieć, kiedy powstrzymać rękę.', 0),
(1532, 'koKR', 'Na razie dam ci to, czego potrzebujesz, by skupiać swoje czary i przyzywać duchy powietrza. Weź ten totem, a gdy będziesz $ggotów:gotowa;, ćwicz ze mną dalej.', 0),
(1840, 'koKR', 'Witaj, $N. Jestem Orm, a Thun\'grim mówi mi, że chcesz, bym wykonał dla ciebie hełm?', 0),
(1844, 'koKR', '$GWykonałeś:Wykonałaś; zadanie, $N, i $gpokazałeś:pokazałaś; mi swoją wartość i determinację. Hełm będzie twój...', 0),
(1845, 'koKR', 'Daję ci ten hełm.$B$BDo mnie przywiodły cię wielkie czyny, $N, a jeśli Matka Ziemia pozwoli... jeszcze większe czekają cię w przyszłości.', 0),
(2280, 'koKR', 'Cóż to takiego?$b$bImponujące, $gmłodzieńcze:młoda;! W tych dyskach wyczuwam sekrety, które ziemia przez wiele lat mocno skrywała. Mądrze $gpostąpiłeś:postąpiłaś;, przynosząc je do mnie.', 0),
(2440, 'koKR', 'Cóż, $N, $gmusiałeś:musiałaś; bardzo zadowolić mędrca Poszukiwacza Prawdy, skoro dał ci ten przedmiot. Otrzymasz też podarunek z jego zapasu mikstur; w nagrodę możesz wybrać 5 doskonałych mikstur leczenia albo 5 większych mikstur many.', 0),
(2860, 'koKR', 'Ach tak, przysłał cię Jangdor. Cieszę się, że jeden z moich najlepszych uczniów ma teraz własnego ucznia.$b$bJego oddanie i talent do pracy ze skórą robią wrażenie. To, że tak cię chwali w tym liście, jest oznaką szacunku, którą uznaję.$b$bWiem, że nauczył cię sztuki pracy z dziką skórą. Pozwól, że dopełnię twoje szkolenie tym wykrojem. Zrób z niego dobry użytek; niewielu na świecie zna sekrety płaszczy z dzikiej skóry.', 0),
(2965, 'koKR', 'Głęboko na pustyni Tanaris leży miejsce zwane Doliną Strażników. Dyski, które $godzyskałeś:odzyskałaś;... ich przetłumaczone glify wspominają o miejscu zwanym Uldum. Większość uważa je za mit.$B$BWiem, że to nieprawda; Uldum istnieje. Byłam tam. No... przynajmniej przed wejściem.$B$BSedno jest takie, $N: sądzimy, że istnieje związek między dyskami a Uldum, i chcemy, żebyś się tam $gudał:udała;.', 0),
(2966, 'koKR', 'Gdy dotykasz piedestału, miniaturowe dyski z Uldamanu brzęczą i jarzą się w twoim plecaku. Znajome mrowienie przebiega ci po dłoniach, a przed wrotami Uldum ożywa obraz kolejnego Kamiennego Obserwatora.$B$B„Pozdrowienia. Jestem strażnikiem wejścia. Dyskom użytym do uzyskania dostępu brakuje właściwych dysków wejściowych – Płyt Uldum. Proszę włączyć te płyty do struktury dysków i powtórzyć sekwencję dostępu. Dziękuję.”', 0),
(2967, 'koKR', 'Brakowało ci kilku dysków? Co ciekawe, wygląda na to, że dyski Norgannona to tylko część całego zestawu – jak klucze na kółku, można by rzec.$B$BJeśli znajdziemy Płyty Uldum, będziemy mogli dostać się do samego kompleksu Uldum. Nie wiem, czy ta perspektywa powinna mnie cieszyć, czy przerażać.$B$BByć może będziemy musieli zaryzykować wszystko, by te sekrety ziemi, które mogłyby nas wszystkich zgubić, pozostały po prostu sekretami.', 0),
(2968, 'koKR', 'Zgadzamy się więc wszyscy – najlepiej będzie zaczekać, aż zawęzimy obszary, na których mogą być ukryte te płyty. $GDoprowadziłeś:Doprowadziłaś; nas tak daleko, $N, i mam nadzieję, że to ty znów wyruszysz w teren, by zmierzyć się z sekretami Uldum.$B$BTymczasem pozwól, że dam ci to honorarium; powinno pokryć wszelkie wydatki, jakie $gponiosłeś:poniosłaś;, pomagając nam, i jeszcze trochę ponad to. Zajrzyj do nas niebawem... Uldum wzywa nas wszystkich, $gmłodzieńcze:młoda;.', 0),
(3369, 'koKR', 'Przysłała cię Falla? No cóż, zobaczmy ten odłamek, o którym, jak mówisz, tak niechętnie mówiła...$B$B<Hamuul wpatruje się w odłamek>$B$BOch... Nie... No cóż.$B$B$N, dziękuję, że mi to $gprzyniosłeś:przyniosłaś;. Radzę ci jednak nie rozprawiać o takich sprawach. Nie powinny cię one zajmować.$B$BPowiedzmy tylko, że w Szmaragdowym Śnie dzieje się inaczej, niż sądziliśmy...$B$BByć może w przyszłości nasze ścieżki znów się skrzyżują.$B$B', 0),
(3518, 'koKR', 'Ach, nareszcie tablica Beth\'Amara. Zastanawiałam się, czy moja współpraca z Jedigą zawiodła, czy może biedna orczyca znalazła śmierć w Aszarze. Cieszę się, że jej się powiodło.$b$bBeth\'Amara był jednym z najbardziej wpływowych alchemików wśród Wysoko Urodzonych. Mówiono, że tylko ten czarodziej opanował między innymi transmutację metali.', 0),
(3562, 'koKR', 'Ach, dobrze. Była o wiele rozsądniejsza, niż się spodziewałam... przynajmniej wobec ciebie. Wręcz spodziewałam się, że każe cię ukarać za moją zuchwałość, bo wysłałam kogoś w swoim zastępstwie. Musi jej naprawdę zależeć na tej tablicy. Ciekawe.$b$bTrzeba będzie się nad tym kiedyś zastanowić.', 0),
(3761, 'koKR', 'O tak, $gszeregowy:szeregowa; $N, tylko nie wysilaj się, żeby pomóc mi zrzucić tę ziemię na kopce! Gdyby Wielkie Duchy chciały, żeby to było zrobione, to by ją tam cudem przeniosły, no nie?!$B$BArcydruid Runiczny Totem chce z tobą znowu porozmawiać, ale przy jego następnym zadaniu przyda ci się znajomość ziołozbieractwa na poziomie czeladnika. Jeśli jednak jej nie masz, i tak znajdzie dla ciebie zajęcie.', 0),
(3786, 'koKR', 'Dobra robota, $N. Na pewno przekażę je samemu arcydruidowi, gdy będzie ich potrzebował. Tymczasem przyjmij to, proszę, w dowód wdzięczności Kręgu Cenariona.$B$BNa razie nieustannie potrzebujemy jutroziarna; jeśli chcesz nadal nam pomagać, wróć, gdy wyhodujesz go więcej.', 0),
(3804, 'koKR', 'Doskonale – to jutroziarno bez wątpienia przyda się, gdy nadejdzie czas. Wiemy, że nocne elfy prowadzą podobne badania nad tymi ziołami, choć nie wiadomo, do czego je wykorzystają, jeśli cokolwiek odkryją. Arcydruid uważa, że jutroziarno będzie potrzebne, dopóki nie zgłębimy tajemnic tego zioła.$B$BTo dla ciebie, $N. Krąg Cenariona dziękuje ci za nieustające wsparcie.', 0),
(4883, 'koKR', 'Energia tego naszyjnika, $N... Sądzę, że ma tylko jedno źródło.$b$b<Nara zamyka oczy i na chwilę milknie.>$b$bDziczołaki, dziś zagubione i zdezorientowane, nie zawsze takie były. Niegdyś miały swój cel i zostały powołane do służby. Bogini nocnych elfów, Elune, stworzyła te istoty, by strzegły jej najświętszych miejsc.$b$bChoć może ci się wydawać, że ta wiedza ma niewielką wartość, zachęcam cię, byś $gspojrzał:spojrzała; głębiej.$b$bZ czasem zrozumiesz. Dziękuję, że $gprzyniosłeś:przyniosłaś; mi to, $N.', 0),
(4987, 'koKR', 'Mówisz, że to od Mulgrisa? Słyszeliśmy, że chciał nieść pomoc cierpiącym stworzeniom na Plagowiskach, ale tego się nie spodziewaliśmy... to bardzo smutne. Mulgris jest... był dobrym przyjacielem. Będę głęboko opłakiwać jego odejście.$B$BDzięki twojej sumienności jego wysiłki nie poszły na marne. W tej gałęzi zapisano wiele wiedzy o zarazie, którą Plaga szerzy na tych ziemiach. Będziemy ją pilnie badać. A ty przyjmij, proszę, to. To najmniej, co możemy zrobić w podzięce za twój szlachetny trud.', 0),
(5062, 'koKR', 'Dobrze, $gzebrałeś:zebrałaś; potrzebną ilość agawy zapalającej. To rzadkie zioło, rosnące tylko w Tysiącu Filarów, pomoże rozpalić uśpiony święty ogień życia.$b$b<Magata zaczyna zaklinać agawę zapalającą.>', 0),
(5088, 'koKR', 'To nie ma sensu. Dlaczego Arikara miałaby polować na Kairna Krwawego Kopyta? Magata nie mogła się pomylić, to nasza najpotężniejsza szamanka.$B$B<Motega kręci głową.>$B$BTak czy inaczej, twój wielki czyn dla Hordy nie przejdzie bez echa – proszę, wybierz jedną z tych rzeczy w nagrodę za pomoc.', 0),
(5722, 'koKR', 'Ciało wygląda na mocno pobite pałkami lub pięściami, ale większość odzieży i ekwipunku wciąż zdaje się być na miejscu. Najwyraźniej troggi nie przywiązują zbytniej wagi do dóbr materialnych.$B$BZaczynasz przeszukiwać ciało w poszukiwaniu czegokolwiek, co mogłoby pomóc Magacie.', 0),
(5723, 'koKR', 'Cieszę się, że $gpotraktowałeś:potraktowałaś; zadanie Magaty poważnie. Dziękuję, $N. Jestem pewien, że troggom trudniej będzie wydostawać się na powierzchnię, skoro ich liczba tak bardzo zmalała.$B$BMoże w przyszłości znajdziemy czas, by ustalić, skąd przybyły te stworzenia i czego naprawdę chcą.', 0),
(5724, 'koKR', 'Doskonale, $N. Dziękuję.$b$bMagata powiedziała mi, że jeśli uda ci się odnaleźć jej współplemieńca, mam ci dać to. Proszę, przyjmij to w podzięce.', 0),
(5932, 'koKR', 'Witaj z powrotem, $N. Czuję, że twoje pierwsze spotkanie z Wielkim Duchem Niedźwiedzia wyglądało tak samo jak u wszystkich druidów, którzy wkraczają na ścieżkę Pazura... było nieco oszałamiające, ale bardzo intensywne. Wiem, że ze mną było tak samo.$B$BWielki Duch Niedźwiedzia jest częścią Azeroth, odkąd Azeroth istnieje na niebiosach. My, taureni, uważnie wsłuchujemy się w takie duchy i wszyscy czerpiemy z ich powołania. Nadszedł czas na twoją pierwszą próbę tego powołania. Słuchaj uważnie...', 0),
(6126, 'koKR', 'Witaj, $gmłody druidzie:młoda druidko;. Cieszę się, że jesteś $ggotów:gotowa; i $gchętny:chętna;, by nauczyć się leczenia zatruć.$B$BDawniej większość druidów przechodziła zaplanowane z góry próby, lecz twoja praca nie będzie niczym takim. Na Rozdrożu na Pustkowiach doszło do fali zatruć zwierząt i nie potrafią sobie z nią poradzić. Ktoś stamtąd poprosił Gaj Luny o pomoc, więc wysyłamy tam ciebie. To nie ćwiczenie – twoja praca będzie jak najbardziej prawdziwa. Pamiętaj o tym.', 0),
(6130, 'koKR', 'Witaj z powrotem. Od twojego odejścia śledziłem postępy w tej lekcji i muszę przyznać, że zaskoczyło mnie to, co dzieje się na Rozdrożu. Trzeba to będzie dokładniej zbadać, bo wprowadzanie takich trucizn do środowiska bardzo zaburza równowagę.$B$BW trudnej sytuacji $gzachowałeś:zachowałaś; spokój i godność. Nie znajduję lepszej nagrody niż trwała władza nad trucizną. Korzystaj z niej dobrze, $N... korzystaj dobrze.', 0),
(6362, 'koKR', 'Ach, nowa wiązka skór. Od razu biorę się do pracy!$B$BDziękuję, $Gbracie:siostro;. $GOddałeś:Oddałaś; mi wielką przysługę. Oto trochę monet za twój czas i koszty podróży.', 0),
(6363, 'koKR', 'Musisz zanieść to na Rozdroże, co? Żaden problem. Jeśli już tam $gbyłeś:byłaś; i $grozmawiałeś:rozmawiałaś; z Devrakiem, możesz polecieć do niego jedną z moich wiwern.', 0),
(6364, 'koKR', 'Ahanu przysłał mi gotowe wyroby? Bardzo dobrze. Na Rozdrożu jest teraz wielu łowców i poszukiwaczy przygód, a interes kwitnie. Na pewno szybko sprzedam te towary.$B$BDziękuję za cały twój trud, $N. Jestem twoim dłużnikiem.', 0),
(6561, 'koKR', 'Kelris od dawna wymykał się Argentowemu Brzaskowi.$B$BPrzez pewien czas uważano go za zmarłego albo zaginionego.$B$BKładąc kres jego panowaniu, $gocaliłeś:ocaliłaś; życie wielu niewinnych, $N.$B$BChwała Matce Ziemi! Składać kogoś w ofierze słudze Przedwiecznego dla własnej korzyści – to odrażające ponad wszelką miarę!$B$B$GDokonałeś:Dokonałaś; dziś wielkiej rzeczy. Kelris był istotą zła i czcząc takie istoty jak Przedwieczni, chciał przywrócić światu czasy chaosu. Dziękuję ci, $N.', 0),
(8861, 'koKR', 'Och, bardzo dobrze! Te zapasy pomogą wykarmić wszystkich, którzy przybyli tu świętować Nowy Rok!$B$BDziękuję ci, $N. Jestem twoją dłużniczką. Proszę, weź te monety... i posłuchaj mojej rady – pij śmiało z beczek na zewnątrz i dołącz do biesiadników w świątecznym tańcu!', 0),
(11204, 'koKR', 'Naprawdę powiedział, że Ponure Totemy to jego najwięksi klienci? Mosarn pomógł nam bardziej, niż mu się wydaje. Skoro tyle wskazuje na Ponure Totemy, chyba właśnie znaleźliśmy pierwszych podejrzanych.', 0),
(13986, 'koKR', 'Och, moja tarcza! Prędko jej nie użyję, ale dziękuję. Nie znoszę tego, że siedzę tu bezużyteczna, kiedy mogłabym pomagać na froncie, ale walka z takim ramieniem nikomu nie pomoże.$b$bUważaj na siebie, dobrze?', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(31, 'koKR', 'Twój powrót do Gromowych Urwisk nie przeszedł bez echa, ale zanim nauczę cię postaci wodnej, potrzebuję dowodu na to, czego $gnauczyłeś:nauczyłaś; się w Gaju Luny.$B$BMasz wisior lwa morskiego?', 0),
(264, 'koKR', 'Kamień jest zimny w dotyku i wyraźnie zniszczony. Wokół walają się śmieci, płaskorzeźbę na wieku trumny znaczą rysy i wyszczerbienia, a roślinność wokół grobu zaczyna go już zarastać.$b$bNikogo nie obchodzi ten, kto tu spoczywa, a już zwłaszcza nie ofiary zarazy.', 0),
(744, 'koKR', 'Ten pióropusz z pewnością będzie wspaniałym darem dla mojego brata.', 0),
(768, 'koKR', 'Witaj ponownie. $GPolowałeś:Polowałaś;? Masz dla mnie skóry?', 0),
(769, 'koKR', 'Masz moje materiały, $N?', 0),
(853, 'koKR', 'Masz coś od aptekarza Helbrima?', 0),
(914, 'koKR', 'Wspomnienia koszmarów wciąż mnie prześladują, $N. $GPokonałeś:Pokonałaś; przywódców Kła i $gzdobyłeś:zdobyłaś; ich klejnoty?', 0),
(962, 'koKR', 'Nie mogę się doczekać, by zobaczyć, czy zdołasz zebrać w Zawodzącej Pieczarze dość wężokwiatu. Wysłałam tam wielu na swoje polecenie, lecz nikt nie wrócił.', 0),
(1049, 'koKR', 'Kairn to dzielny i szlachetny przywódca i powierzyłbym mu własne życie. Nie ufam jednak innym w obecnym klimacie politycznym.$b$bGdy zdołam zebrać całą dostępną wiedzę, będę mógł udzielić wodzowi rozważnej rady.$b$bUdało ci się już wyruszyć do Polan Tirisfal? Do Szkarłatnego Klasztoru? Kompendium Poległych to tylko jeden element tej zawiłej układanki...', 0),
(1065, 'koKR', 'Ach, $gprzyszedłeś:przyszłaś; z moimi nowymi obiektami badań?', 0),
(1066, 'koKR', '$GZnalazłeś:Znalazłaś; magów cienia z Syndykatu i $gzebrałeś:zebrałaś; od nich krew?', 0),
(1067, 'koKR', '$GWróciłeś:Wróciłaś;, $N. Przynosisz pomoc od aptekarza Lydona?', 0),
(1086, 'koKR', 'Musisz odnaleźć lądowisko spółki Gitgeszeft, jeśli istnieje, $N.', 0),
(1102, 'koKR', 'Gdy będę wiedział, że plugawe bestie z Cierniska Brzytwoskórych zostały wypędzone ze swojego plugawego legowiska, będę mógł spocząć w spokoju, wiedząc, że zemsta się dokonała.$b$b$GWypędziłeś:Wypędziłaś; kolcozwierze z Cierniska? Przynosisz mi dobrą wieść w postaci serca Brzytwobokiej?', 0),
(1131, 'koKR', '$GPokonałeś:Pokonałaś; plugawego Stalokłapa, $N?', 0),
(1136, 'koKR', '$GByłeś:Byłaś; w Górach Alterak, $N? $GStanąłeś:Stanęłaś; do walki z nieuchwytną Mroźną Paszczą?', 0),
(1195, 'koKR', 'Gdy będziemy mieli napełnioną fiolkę, prześlemy ją mojemu współpracownikowi, Rauowi, do Tysiąca Filarów. To on poprosił o fiolkę wody, więc lepiej będzie wiedział, jak możemy ją wykorzystać.', 0),
(1196, 'koKR', 'Nie przysłał cię przypadkiem Zangen, hm?', 0),
(1197, 'koKR', 'Nie mogę się doczekać, aż wezmę w ręce rozszczepione kopyto. $GZdobyłeś:Zdobyłaś; je już?', 0),
(1205, 'koKR', 'Masz ząb Martwego Bagna, $N? $GZakończyłeś:Zakończyłaś; cierpienia tego stworzenia?', 0),
(1276, 'koKR', 'Witaj, $N. W czym mogę ci pomóc?', 0),
(1489, 'koKR', 'Twoi panowie są głupcami, skoro cię tu przysłali, bo już nigdy nie będę niewolnikiem Plagi!', 0),
(1844, 'koKR', 'Masz róg? Czy matriarcha jest już wolna od bólu?', 0),
(2280, 'koKR', 'Tak, $gmłodzieńcze:młoda;, widzę, jak wkraczasz do mojego namiotu pewnym krokiem... z determinacją w swoim celu. Szukasz mojej rady w jakiejś sprawie wielkiej wagi dla Hordy? A może chcesz, bym odsłonił przed tobą jakąś tajemnicę wszechświata?', 0),
(2440, 'koKR', 'Witaj, $N! Przychodzisz na naukę alchemii, a może w innej sprawie?', 0),
(2860, 'koKR', 'Witaj, $gwędrowcze:wędrowczyni;... Po twoim obliczu widzę, że podobnie jak ja jesteś $gkaletnikiem:kaletniczką;. Przychodzisz czerpać z moich umiejętności, a może masz do mnie inną sprawę?', 0),
(2966, 'koKR', 'Ten znajomo wyglądający piedestał wystaje z gorącego piasku. Być może jego obecność tutaj coś znaczy...', 0),
(2967, 'koKR', 'Witaj z powrotem, $N. Udało ci się wykorzystać dyski, czy wszystko na nic?', 0),
(3518, 'koKR', 'Tak, $N? Co mogę dla ciebie zrobić? Mam wiele spraw na głowie, więc proszę, streszczaj się.', 0),
(3562, 'koKR', 'No i co powiedziała Magata? Stara wiedźma... Założę się, że nie była zbyt uprzejma.', 0),
(3761, 'koKR', 'Spocznij, $gszeregowy:szeregowa;. Jeśli $gprzyszedłeś:przyszłaś; zrzucić ziemię z Un\'Goro – to świetnie! A jeśli nie, znikaj.', 0),
(3786, 'koKR', 'Tak, $N? $GWyhodowałeś:Wyhodowałaś; trochę jutroziarna do ważnych badań arcydruida? Tajemnicze właściwości Krateru Un\'Goro z każdym dniem stają się jaśniejsze dzięki twojej pomocy.', 0),
(3804, 'koKR', 'Arcydruid wciąż szuka więcej jutroziarna do projektu badawczego Kręgu Cenariona dotyczącego Krateru Un\'Goro. Przyjmujemy je po dziesięć sztuk i w zamian dajemy skrzynkę przydatnych rzeczy. Gdy będziesz mieć dziesięć, daj mi znać, a odpowiednio cię wynagrodzę.', 0),
(4883, 'koKR', 'W czym mogę ci pomóc, $N?', 0),
(4987, 'koKR', 'W imieniu Kręgu Cenariona witam cię w tej enklawie, $N. Co cię do nas sprowadza?', 0),
(5062, 'koKR', 'A więc Motega Ognista Grzywa przysyła wieści o Arikarze... to doprawdy poważne wieści.$B$B<Magata rozgląda się dookoła.>$B$BArikara to zabójcza istota, zrodzona tylko po to, by mścić się na tych, którzy dopuścili się haniebnych czynów.$B$B<Magata się uśmiecha.>', 0),
(5088, 'koKR', '$GZabiłeś:Zabiłaś; okrutną wężycę Arikarę, $N?', 0),
(5723, 'koKR', 'Jak idą poszukiwania Rozpadliny? A troggi?$B$BNie możemy pozwolić, by to zagrożenie trwało – jeśli nie ustanie, ucierpią na tym nasi bracia orkowie.', 0),
(5724, 'koKR', 'Udało ci się coś znaleźć, $N? Przyda się każda wskazówka, dlaczego jeden z jej współplemieńców musiał niepotrzebnie zginąć.', 0),
(6002, 'koKR', 'Gdy zmierzysz się z czekającym cię wyzwaniem, w pełni pojmiesz, czym jest siła ciała i siła serca. Do tego czasu nie mogę ci bardziej pomóc.', 0),
(6362, 'koKR', 'Na twoich ramionach jest kurz, który musi pochodzić z Pustkowi. $GRozmawiałeś:Rozmawiałaś; z moim przyjacielem Jahanem?', 0),
(6363, 'koKR', 'Witaj. Co mogę dla ciebie zrobić?', 0),
(6364, 'koKR', '$N, $gwróciłeś:wróciłaś; z Gromowych Urwisk? $GDostarczyłeś:Dostarczyłaś; skóry Ahanu?', 0),
(6561, 'koKR', 'Niech Matka Ziemia będzie z tobą, $N.$B$BNaszym celem powinien być pokój między ziemią a wszystkimi jej dziećmi. Ona ma wielki zamysł wobec natury, a każdy z nas ma w nim do odegrania swoją rolę.', 0),
(7820, 'koKR', 'Obecnie przyjmujemy dary w postaci wełnianego płótna. Dar sześćdziesięciu sztuk wełnianego płótna zapewni ci pełne uznanie Gromowych Urwisk za twoją hojność. Nasze zapasy wełny są takie, że od ciebie potrzebujemy łącznie tylko sześćdziesięciu sztuk; resztę, niezbędną do powodzenia zbiórki, powinniśmy zdobyć od innych w królestwie.$B$BJeśli masz przy sobie sześćdziesiąt sztuk wełnianego płótna i chcesz je ofiarować, mogę je teraz od ciebie przyjąć.', 0),
(7822, 'koKR', 'Kończy się nam tkanina magów i przydałaby się twoja pomoc w uzupełnieniu zapasów! Licząc na całą społeczność, potrzebujemy od ciebie daru zaledwie 60 sztuk tkaniny magów, by osiągnąć nasz cel. Zapewniam cię, że taka hojność nie umknie uwadze Gromowych Urwisk!$B$BJeśli masz przy sobie sześćdziesiąt sztuk tkaniny magów i chcesz je ofiarować, mogę je teraz od ciebie przyjąć.', 0),
(8861, 'koKR', 'Dzień dobry! $GPrzybyłeś:Przybyłaś; do Gromowych Urwisk na nasze obchody? A może chcesz dać odpocząć zmęczonemu kopytu między łowami?', 0),
(13986, 'koKR', 'Och! Witaj. Chyba się nie znamy; mogę coś dla ciebie zrobić?', 0);
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES
(3050, 0, 'koKR', 'Taureni są synami i córkami Matki Ziemi i okazujemy szacunek wszystkim jej dzieciom. Nawet zwierzęta, które zabijamy, są nam drogie, bo ich ciała dają nam pożywienie, a ich skóry – ciepło.', 0),
(3390, 0, 'koKR', 'Pustkowia kryją bogactwo substancji, z których my, aptekarze Lordaeronu, możemy zrobić użytek.', 0),
(3419, 0, 'koKR', 'Aby nasz lud przetrwał, musimy zgłębiać drogi natury i poznawać jej sekrety.', 0),
(4046, 0, 'koKR', 'Musisz słuchać, $gmłody:młoda; $N. Słuchaj szeptów w ciemności, bo niosą wskazówki w tych niespokojnych czasach.', 0),
(5770, 0, 'koKR', 'Jeśli mamy chronić naturę, musimy przyjąć jej siłę. I musimy okazać tę siłę tym, którzy chcieliby skrzywdzić ziemię.', 0),
(10428, 0, 'koKR', 'Posterunek Białego Zasięgu zaczynał jako mały obóz myśliwski... Teraz każdy chce tu rozkręcić interes i nazwać to miejsce domem.$B$B<Motega wzrusza ramionami>', 0);
