INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(442, 'koKR', 'Aby stanąć do walki z Mroźną Paszczą, musisz go zwabić mięsem jego ulubionej zdobyczy.$B$BUdaj się w Góry Alterak w Azeroth i upoluj potężnego lwa górskiego. Zabij go, a potem zanieś jego truchło do Jaskini Bez Wzrostu, miejsca uznawanego za święte przez dzikie wendigo.$B$BPołóż truchło na Płomieniu Uzela, a woń palonego mięsa rozejdzie się z jaskini.$B$BA wtedy, z czasem, przyjdzie Mroźna Paszcza.$B', 0),
(448, 'koKR', 'Aptekarzu Lydonie,$B$Bmam nadzieję, że ten list dotrze do ciebie szybko, a jego okaziciel w dobrym zdrowiu. W dalekim Kalimdorze pojawiła się potrzeba, która, jak sądzę, będzie wymagać twoich umiejętności.$B$BBędę się streszczać.$B$BW Górach Szponogłazach, niedaleko Mulgoru, ojczyzny naszych sprzymierzeńców taurenów, narasta kryzys. Prowadzona przez gobliny Spółka Gitgeszeft zaciekle wydobywa rudę i wycina drzewa w tych górach, rozwścieczając duchy gór.', 0),
(449, 'koKR', 'Muszę przyjąć, że zamęt, jaki te duchy wywołują w kanałach pozostających pod pieczą taureńskich szamanów i druidów, odwraca ich uwagę. Taureni uważają bowiem Spółkę Gitgeszeft w Górach Szponogłazach za poważne zagrożenie.$B$BZagrożenie czy nie, musimy pomóc naszym sprzymierzeńcom.$B$BLydonie, masz rozległą wiedzę o toksynach. Czy zdołasz opracować taką, którą moglibyśmy rozsiać zarazę wśród goblinów w Szponogłazach?$B$BZ uczonym pozdrowieniem$BP. Zamah', 0),
(572, 'koKR', 'Po sukcesie Kel\'Thuzada w Lordaeronie Król Lisz poczynił ostatnie przygotowania do ataku na ludzką cywilizację. Umieścił energię swojej zarazy w kilku przenośnych artefaktach zwanych kotłami zarazy, po czym Ner\'zhul rozkazał Kel\'Thuzadowi przewieźć kotły do Lordaeronu i ukryć je w różnych wioskach kontrolowanych przez kult. ', 0),
(573, 'koKR', 'Kotły, strzeżone przez wiernych kultystów, miały działać jak generatory zarazy, która sączyła się na niczego niepodejrzewające pola uprawne i miasta północnego Lordaeronu. Plan Króla Lisza powiódł się doskonale. Wiele północnych wiosek Lordaeronu zostało skażonych niemal natychmiast. Tak jak w Północnej Grani, mieszkańcy, którzy zarazili się zarazą, umierali i powstawali jako posłuszni niewolnicy Króla Lisza. ', 0),
(574, 'koKR', 'Kultyści pod wodzą Kel\'Thuzada pragnęli umrzeć i powstać na nowo w służbie swego mrocznego pana. Radowali się na myśl o nieśmiertelności w nieumarłym życiu. W miarę jak zaraza się szerzyła, na północnych ziemiach powstawało coraz więcej dzikich zombie. Kel\'Thuzad spojrzał na rosnącą armię Króla Lisza i nazwał ją Plagą – bo wkrótce miała ruszyć na bramy Lordaeronu... i zetrzeć ludzkość z powierzchni świata. ', 0),
(2295, 'koKR', 'Przed Erą Pamięci łagodna Matka Ziemia tchnęła na złote mgły świtu. Tam, gdzie spoczęły bursztynowe obłoki, rozpostarły się bezkresne pola falującej pszenicy i jęczmienia. Była to kolebka jej dzieł – wielki kosz życia i nadziei.', 0),
(2296, 'koKR', 'Oczy Matki Ziemi świeciły nad ziemiami, które tchnieniem powołała do istnienia. Jej prawe oko, An\'she (słońce),\n dawało ziemi ciepło i światło. Jej lewe oko, Mu\'sha (księżyc),\n dawało spokój i sen budzącym się stworzeniom świtu. Taka była moc jej spojrzenia, że Matka Ziemia zamykała jedno śniące oko przy każdym obrocie nieba. Tak jej pełne miłości spojrzenie zamieniało dzień w noc podczas pierwszego świtu świata. $B', 0),
(2297, 'koKR', 'Podczas gdy prawe oko świeciło nad złotym świtem, łagodne dłonie Matki Ziemi rozpostarły się nad złotymi równinami. Wszędzie, gdzie padł cień jej ramion, z żyznej gleby powstawał szlachetny lud. Shu\'halo (taureni) powstali, by składać dzięki i modlitwy swojej kochającej matce. Tam, na bezkresnych polach świtu, dzieci ziemi oddały się jej łasce i przysięgły błogosławić jej imię aż do ostatniego zmierzchu świata.', 0),
(2298, 'koKR', 'Gdy dzieci ziemi wędrowały po polach świtu, usłyszały mroczne szepty dobiegające z głębi świata. Szepty uczyły dzieci sztuki wojny i podstępu. Wielu Shu\'halo uległo władzy cienia i przyjęło drogę złości i niegodziwości. Zwrócili się przeciw swoim czystym braciom i porzucili niewinność, pozwalając jej dryfować po równinach.', 0),
(2299, 'koKR', 'Matka Ziemia, której serce ciążyło z powodu niedoli dzieci, nie mogła patrzeć, jak tracą jej łaskę. W swoim żalu wyrwała sobie oczy i puściła je w wirujący lot po bezkresnym, gwiaździstym niebie. An\'she i Mu\'sha, pragnąc ukoić nawzajem swój smutek, mogły jedynie gonić się po niebie za swoim nikłym blaskiem. Bliźnięta wciąż się gonią przy każdym obrocie świata.', 0),
(2300, 'koKR', 'Choć niewidoma, Matka Ziemia nie mogła długo oddalać się od świata swego serca. Nadstawiała ucha wiatrom i słuchała wszystkiego, co działo się na polach świtu. Jej wielkie serce zawsze było przy dzieciach – a jej pełna miłości mądrość nigdy ich nie opuściła.', 0),
(2301, 'koKR', 'W dzielne serca swoich czystych dzieci Matka Ziemia włożyła umiłowanie łowów. Stworzenia pierwszego świtu były bowiem dzikie i groźne. Kryły się przed Matką Ziemią, znajdując schronienie w cieniach i dzikich zakątkach krainy. Shu\'halo polowali na te bestie, gdziekolwiek je znaleźli, i oswajali je z błogosławieństwem Matki Ziemi. ', 0),
(2302, 'koKR', 'Jeden wielki duch jednak im się wymykał. Apa\'ro (znany nocnym elfom jako Malorne),\n był dumnym jeleniem o śnieżnobiałej sierści. Jego poroże drapało sklepienie niebios, a potężne kopyta wydeptały głębiny świata. Shu\'halo ścigali Apa\'ro po najdalszych zakątkach budzącego się świata – i zacieśniali krąg, by schwytać dumnego jelenia.', 0),
(2303, 'koKR', 'Chcąc uciec, wielki jeleń skoczył w niebo. Jednak gdy ucieczka wydawała się pewna, jego potężne poroże zaplątało się w gwiazdy, które mocno go uwięziły. Choć kopał i się szamotał, Apa\'ro nie zdołał uwolnić się z niebios. Wtedy znalazła go Mu\'sha, która goniła swego brata An\'she ku świtowi. Mu\'sha ujrzała szamoczącego się potężnego jelenia i od razu się w nim zakochała. ', 0),
(2304, 'koKR', 'Lady Mara Fordragon, Wielka Kapłanka Wichrogrodu, opiekunka uchodźców, którzy zbiegli do Lordaeronu po Pierwszej Wojnie. Była jasną matką naszej przyszłości. Niech spoczywa w Światłości. ', 0),
(2305, 'koKR', 'Z czasem dziecię, Cenarius, dorównało postawą swemu dumnemu ojcu. Brat drzew i gwiazd, wielki łowca przemierzał dalekie zakątki świata, śpiewając harmonijne pieśni świtu. Wszystkie stworzenia chyliły czoła przed jego wdziękiem i pięknem – nikt nie był tak przebiegły jak syn księżyca i białego jelenia. ', 0),
(2306, 'koKR', 'W końcu Cenarius zaprzyjaźnił się z Shu\'halo i opowiadał im o obracającym się świecie. Dzieci ziemi uznały go za brata i przysięgły pomagać mu w opiece nad polami życia i ulubionymi stworzeniami ich wielkiej Matki Ziemi. ', 0),
(2307, 'koKR', 'Cenarius nauczył dzieci ziemi rozmawiać z drzewami i roślinami. Shu\'halo stali się druidami i dokonywali wielkich czynów magii, by przywracać ziemi zdrowie. Przez wiele pokoleń Shu\'halo polowali u boku Cenariusa i chronili świat przed cieniami, które poruszały się pod nim.', 0),
(2308, 'koKR', 'Gdy mgły świtu się rozwiały, a Era Pamięci postępowała, półbóg Cenarius poszedł własną drogą przez pola świata. Shu\'halo (taureni) smucili się jego odejściem i zapomnieli wiele z druidyzmu, którego ich nauczył. Wraz z upływem pokoleń zapomnieli, jak rozmawiać z drzewami i dzikimi stworzeniami krainy. Mroczne szepty z głębin świata znów zaczęły docierać do ich uszu.', 0),
(2309, 'koKR', 'Choć dzieci ziemi zamknęły uszy na złe szepty, na ich wędrowne plemiona spadła straszliwa klątwa. Z czarnych ziem zachodu nadciągnęła horda morderczych stworzeń – centaurów. Kanibale i łupieżcy, centaury spadły na Shu\'halo niczym zaraza. Choć wojownicy i łowcy walczyli z błogosławieństwem Matki Ziemi w sercach, centaurów nie dało się pokonać.', 0),
(2310, 'koKR', 'Cenarius nauczył dzieci ziemi rozmawiać z drzewami i roślinami. Shu\'halo stali się druidami i dokonywali wielkich czynów magii, by przywracać ziemi zdrowie. Przez wiele pokoleń Shu\'halo polowali u boku Cenariusa i chronili świat przed cieniami, które poruszały się pod nim. ', 0);
