INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(1076, 'koKR', '%s umieszcza zarodniki w swoich przyrządach alchemicznych...', '', 0),
(1077, 'koKR', 'Ach, dobrze. Te zarodniki ładnie się przetworzyły. Dziękuję, $n.', '', 0),
(1085, 'koKR', '%s ogląda skorupy kłapaczy...', '', 0),
(1087, 'koKR', 'Hm...', '', 0),
(1088, 'koKR', 'Dziwne. Bardzo dziwne...', '', 0),
(1089, 'koKR', '$n. Te skorupy wiele mi mówią, ale obawiam się, że rodzą teraz o wiele więcej pytań...', '', 0),
(1297, 'koKR', 'Wściekłość Ishamuhale płynie w tobie, $n.', '', 0),
(1298, 'koKR', 'Lakota\'mani grzmi w tobie, $n.', '', 0),
(1299, 'koKR', 'Szybkość Owatanki jest z tobą, $n.', '', 0),
(1300, 'koKR', 'Twoja ścieżka jest pewna, $n, bo towarzyszy ci determinacja Washte Pawne.', '', 0),
(1416, 'koKR', '', '%s wysłuchuje prośby $n.', 0),
(1417, 'koKR', '', 'Słusznie $gzrobiłeś:zrobiłaś;, że $gprzyszedłeś:przyszłaś;. Moja mądrość będzie twoja.', 0),
(1418, 'koKR', '', '%s się uśmiecha.', 0),
(1419, 'koKR', '', 'Idź, mój sługo. Zanieś aptekarce Zamah wieści ze Szponogłazów.', 0),
(1420, 'koKR', '', '%s przywołuje posłańca...', 0),
(1423, 'koKR', '', '%s napełnia naczynie toksyną.', 0),
(1424, 'koKR', '', 'Toksyna jest gotowa, $n.', 0),
(1648, 'koKR', 'Idź do karczmy „Cienisty Wypoczynek” i podążaj za śladami. Zobacz, dokąd prowadzą, i wróć do mnie z raportem.', '', 0),
(1755, 'koKR', 'Kagoro, wzywam cię!', '', 0),
(2635, 'koKR', 'Skończyłem twój hełm, $n.', '', 0),
(2824, 'koKR', 'Daj odpocząć strudzonym kościom.', 'Daj odpocząć strudzonym kościom.', 0),
(3443, 'koKR', 'Szukasz byka imieniem Krumn. Znajdziesz go na niższym wzniesieniu, w Informacji miejskiej Gromowych Urwisk.', 'Szukasz byka imieniem Krumn. Znajdziesz go na niższym wzniesieniu, w Informacji miejskiej Gromowych Urwisk.', 0),
(3444, 'koKR', 'Bank Gromowych Urwisk znajdziesz na niższym wzniesieniu.', 'Bank Gromowych Urwisk znajdziesz na niższym wzniesieniu.', 0),
(3445, 'koKR', 'Gniazdo wiwern jest na szczycie totemowych schodów w środku miasta.', 'Gniazdo wiwern jest na szczycie totemowych schodów w środku miasta.', 0),
(3452, 'koKR', 'Odszukaj Turaka Runiczny Totem w Sali Starszych na Wzniesieniu Starszych.', 'Odszukaj Turaka Runiczny Totem w Sali Starszych na Wzniesieniu Starszych.', 0),
(3453, 'koKR', 'Ach, w takim razie musisz udać się do Sali Łowców. Na Wzniesieniu Myśliwego znajdziesz kilku wielkich łowców, takich jak Holt Gromoróg.', 'Ach, w takim razie musisz udać się do Sali Łowców. Na Wzniesieniu Myśliwego znajdziesz kilku wielkich łowców, takich jak Holt Gromoróg.', 0),
(3454, 'koKR', 'Wyznawca magii tajemnej, tak? Hmf! No dobrze... znajdziesz ich przy Źródłach Objawień, pod Wzniesieniem Ducha.', 'Wyznawca magii tajemnej, tak? Hmf! No dobrze... znajdziesz ich przy Źródłach Objawień, pod Wzniesieniem Ducha.', 0),
(3455, 'koKR', 'Musisz porozmawiać z Ojcem Cobbem. Znajdziesz go pod Wzniesieniem Ducha, w jaskini Źródeł Objawień.', 'Musisz porozmawiać z Ojcem Cobbem. Znajdziesz go pod Wzniesieniem Ducha, w jaskini Źródeł Objawień.', 0),
(3456, 'koKR', 'Sala Duchów to dom naszych szamanów. Znajdziesz ją na Wzniesieniu Ducha. Niech czuwają nad tobą przodkowie.', 'Sala Duchów to dom naszych szamanów. Znajdziesz ją na Wzniesieniu Ducha. Niech czuwają nad tobą przodkowie.', 0),
(3457, 'koKR', 'Pragniesz kiedyś dołączyć do naszych szeregów? Sark Gniewny Totem pomoże ci w drodze. Jest w Sali Łowców.', 'Pragniesz kiedyś dołączyć do naszych szeregów? Sark Gniewny Totem pomoże ci w drodze. Jest w Sali Łowców.', 0),
(3481, 'koKR', 'W takim razie udaj się do Alchemii Beny na środkowym wzniesieniu i porozmawiaj z samą Beną. Pomoże ci opanować sztukę warzenia mikstur.', 'W takim razie udaj się do Alchemii Beny na środkowym wzniesieniu i porozmawiaj z samą Beną. Pomoże ci opanować sztukę warzenia mikstur.', 0),
(3482, 'koKR', 'Chcesz się nauczyć pracy przy kowadle i młocie, co? Karn Kamienne Kopyto może cię tego nauczyć. Ma kuźnię na niższym wzniesieniu, przy stawie.', 'Chcesz się nauczyć pracy przy kowadle i młocie, co? Karn Kamienne Kopyto może cię tego nauczyć. Ma kuźnię na niższym wzniesieniu, przy stawie.', 0),
(3483, 'koKR', 'Nie ma w Gromowych Urwiskach lepszej kucharki niż Aska Mglisty Bieg. Mmmm, stąd czuję, co gotuje. Idź do jej kuchni na wyższym wzniesieniu.\nA niech to... teraz burczy mi w brzuchu.', 'Nie ma w Gromowych Urwiskach lepszej kucharki niż Aska Mglisty Bieg. Mmmm, stąd czuję, co gotuje. Idź do jej kuchni na wyższym wzniesieniu.\nA niech to... teraz burczy mi w brzuchu.', 0),
(3484, 'koKR', 'W takim razie zajrzyj do Zaklinactwa Świtokroczów na środkowym wzniesieniu. Teg z wielką chęcią pomoże ci, jak tylko będzie mógł.', 'W takim razie zajrzyj do Zaklinactwa Świtokroczów na środkowym wzniesieniu. Teg z wielką chęcią pomoże ci, jak tylko będzie mógł.', 0),
(3485, 'koKR', 'Pierwsza pomoc to zawsze przydatna umiejętność. Nieraz ocaliła mi skórę w bitwie. Odwiedź Duchowe uzdrawianie na Wzniesieniu Ducha. Pand Więź Kamienia nauczy cię wszystkiego, czego trzeba, żeby i ty ocalić swoją skórę.', 'Pierwsza pomoc to zawsze przydatna umiejętność. Nieraz ocaliła mi skórę w bitwie. Odwiedź Duchowe uzdrawianie na Wzniesieniu Ducha. Pand Więź Kamienia nauczy cię wszystkiego, czego trzeba, żeby i ty ocalić swoją skórę.', 0),
(3486, 'koKR', 'Nie dziwię się, że chcesz łowić ryby. Mulgor ma jedne z najlepszych łowisk w południowym Kalimdorze, a „Przynęty i sprzęt wędkarski »Na Szczycie«” na wyższym wzniesieniu mają cały sprzęt, jakiego ci trzeba, żeby z nich skorzystać.\nPowiedz Kahowi Mglisty Bieg, że to ja cię przysyłam!', 'Nie dziwię się, że chcesz łowić ryby. Mulgor ma jedne z najlepszych łowisk w południowym Kalimdorze, a „Przynęty i sprzęt wędkarski »Na Szczycie«” na wyższym wzniesieniu mają cały sprzęt, jakiego ci trzeba, żeby z nich skorzystać.\nPowiedz Kahowi Mglisty Bieg, że to ja cię przysyłam!', 0),
(3487, 'koKR', 'W takim razie porozmawiaj z Kominem Zimowe Kopyto w „Holistycznym Zielarstwie”. Znajdziesz go na środkowym wzniesieniu.', 'W takim razie porozmawiaj z Kominem Zimowe Kopyto w „Holistycznym Zielarstwie”. Znajdziesz go na środkowym wzniesieniu.', 0),
(3488, 'koKR', 'W takim razie idź do Uny w Płatnerzach Gromowych Urwisk. Znajdziesz ich na środkowym wzniesieniu.', 'W takim razie idź do Uny w Płatnerzach Gromowych Urwisk. Znajdziesz ich na środkowym wzniesieniu.', 0),
(3489, 'koKR', 'Brek Kamienne Kopyto jest w Geologii Kamiennego Kopyta na niższym wzniesieniu i może cię nauczyć, jak należycie wydobywać cenne rudy i kamienie.', 'Brek Kamienne Kopyto jest w Geologii Kamiennego Kopyta na niższym wzniesieniu i może cię nauczyć, jak należycie wydobywać cenne rudy i kamienie.', 0),
(3490, 'koKR', 'Tepa słynie ze swoich wyrobów z tkanin. Znajdziesz ją w Płatnerzach Gromowych Urwisk na środkowym wzniesieniu.', 'Tepa słynie ze swoich wyrobów z tkanin. Znajdziesz ją w Płatnerzach Gromowych Urwisk na środkowym wzniesieniu.', 0),
(3492, 'koKR', 'Mooranta pomoże ci nauczyć się oprawiania skór. Znajdziesz ją tuż przed Płatnerzami Gromowych Urwisk na środkowym wzniesieniu.', 'Mooranta pomoże ci nauczyć się oprawiania skór. Znajdziesz ją tuż przed Płatnerzami Gromowych Urwisk na środkowym wzniesieniu.', 0),
(3955, 'koKR', 'Wyglądasz na $gmężczyznę, który:kobietę, która; szuka wiedzy. Może szukasz nauk kuźni i młota. Może mogę poprowadzić cię tą ścieżką. Ale dopiero gdy przyjmiesz duchy i usłyszysz ich wezwanie.', '', 0),
(4258, 'koKR', 'Ludzie zagarnęli dla siebie dużą część Pyłowego Bagniska, ale klan Kamiennych Maczug z naszą pomocą zdołał ich odeprzeć.', '', 0),
(4259, 'koKR', 'Spalona karczma.', 'Spalona karczma.', 0),
(4260, 'koKR', 'Ludzie zbudowali karczmę na skraju Pustkowi. Nazwali ją „Cienisty Wypoczynek”. Kilka tygodni temu spłonęła.$b$bCo mnie to obchodzi? Nie obchodzi – przynajmniej nie los ludzi – ale miałem w tej karczmie szpiega i nie zostawię jego śmierci bez odpowiedzi. Muszę wiedzieć, kto to zrobił.$B$BJeśli chcesz pomóc, idź do ruin karczmy „Cienisty Wypoczynek” i przynieś mi wszelkie ślady, jakie znajdziesz.', '', 0),
(4261, 'koKR', 'Odnaleźć Reethe\'a.', 'Odnaleźć Reethe\'a.', 0),
(4262, 'koKR', 'Jeśli Reethe ma coś wspólnego ze spaleniem karczmy „Cienisty Wypoczynek”, musisz go znaleźć i wyciągnąć z niego jakieś odpowiedzi.$b$bWysłałem Ogrona, żeby go wytropił. Ruszył na południowy wschód, w stronę głównej drogi przez bagna. Spotkaj się z Ogronem, a potem odszukaj Reethe\'a.', '', 0),
(4350, 'koKR', 'Choć nazywamy tę krainę Pustkowiami, dla kogoś, kto wie, gdzie patrzeć, tętni ona życiem.', '', 0),
(4560, 'koKR', 'Nie zbezcześcisz naszej świętej ziemi!', 'Nie zbezcześcisz naszej świętej ziemi!', 0),
(4659, 'koKR', 'Uprzedzam cię, $gżołnierzyku:księżniczko; – nie jestem w nastroju na żadne uwagi, które uważasz za urocze albo zabawne. Jestem tu, żeby dopilnować, by badania arcydruida szły zgodnie z planem, a mam rozkaz wyplenić każdą łamagę, która nie ma tego, czego trzeba, by służyć w moim ukochanym Kręgu Cenariona.', '', 0),
(4660, 'koKR', '', 'Witaj, $gszlachetny:szlachetna; $N. Ta skromna służka Kręgu Cenariona życzy tobie i twoim błogosławieństwa i obfitości.', 0),
(5476, 'koKR', 'Zioła, które daje natura, mogą być potężnym sprzymierzeńcem, jeśli traktuje się je z szacunkiem. Aby kontynuować szkolenie, odszukaj Benę w jej sklepie alchemicznym na środkowym wzniesieniu.', 'Zioła, które daje natura, mogą być potężnym sprzymierzeńcem, jeśli traktuje się je z szacunkiem. Aby kontynuować szkolenie, odszukaj Benę w jej sklepie alchemicznym na środkowym wzniesieniu.', 0),
(5477, 'koKR', 'Ziemskie dobra możesz złożyć w Banku Gromowych Urwisk na niższym wzniesieniu.', 'Ziemskie dobra możesz złożyć w Banku Gromowych Urwisk na niższym wzniesieniu.', 0),
(5478, 'koKR', 'Metalu, jak wszystkiego, należy używać w równowadze z naturą. Karn Kamienne Kopyto ma kuźnię przy stawie na niższym wzniesieniu. Poszukaj jego mądrości.', 'Metalu, jak wszystkiego, należy używać w równowadze z naturą. Karn Kamienne Kopyto ma kuźnię przy stawie na niższym wzniesieniu. Poszukaj jego mądrości.', 0),
(5479, 'koKR', 'Oddajesz cześć duchom zwierząt, które musisz zabić, gdy nic z nich nie marnujesz. Aska Mglisty Bieg pokaże ci, jak to robić. Ma kuchnię na wyższym wzniesieniu.', 'Oddajesz cześć duchom zwierząt, które musisz zabić, gdy nic z nich nie marnujesz. Aska Mglisty Bieg pokaże ci, jak to robić. Ma kuchnię na wyższym wzniesieniu.', 0),
(5480, 'koKR', 'Witaj, $gczcigodny:czcigodna;. Turak Runiczny Totem i pozostali druidzi oczekują cię w Sali Starszych na Wzniesieniu Starszych.', 'Witaj, $gczcigodny:czcigodna;. Turak Runiczny Totem i pozostali druidzi oczekują cię w Sali Starszych na Wzniesieniu Starszych.', 0),
(5481, 'koKR', 'Zaklinanie ukazuje cykl niszczenia i tworzenia, który jest sercem natury. Teg w Zaklinactwie Świtokroczów na środkowym wzniesieniu pokaże ci, jak to robić.', 'Zaklinanie ukazuje cykl niszczenia i tworzenia, który jest sercem natury. Teg w Zaklinactwie Świtokroczów na środkowym wzniesieniu pokaże ci, jak to robić.', 0),
(5482, 'koKR', 'Życie to walka, a powiedzenie, że co cię nie zabije, to cię wzmocni, nie zawsze jest prawdziwe. Czasem rany działają powoli i dlatego mamy bandaże. Pand Więź Kamienia ze Wzniesienia Ducha nauczy cię sztuki pierwszej pomocy.', 'Życie to walka, a powiedzenie, że co cię nie zabije, to cię wzmocni, nie zawsze jest prawdziwe. Czasem rany działają powoli i dlatego mamy bandaże. Pand Więź Kamienia ze Wzniesienia Ducha nauczy cię sztuki pierwszej pomocy.', 0),
(5483, 'koKR', 'Kah Mglisty Bieg z „Przynęt i sprzętu wędkarskiego »Na Szczycie«” na wyższym wzniesieniu pokaże ci, jak odnaleźć wewnętrzny spokój i pogodę ducha, łowiąc ryby na kolejny posiłek.', 'Kah Mglisty Bieg z „Przynęt i sprzętu wędkarskiego »Na Szczycie«” na wyższym wzniesieniu pokaże ci, jak odnaleźć wewnętrzny spokój i pogodę ducha, łowiąc ryby na kolejny posiłek.', 0),
(5484, 'koKR', 'Wspólnota bratnich dusz może być potężną siłą. Krumn pomoże ci ją stworzyć. Znajdziesz go w Informacji miejskiej Gromowych Urwisk na niższym wzniesieniu, obok wind.', 'Wspólnota bratnich dusz może być potężną siłą. Krumn pomoże ci ją stworzyć. Znajdziesz go w Informacji miejskiej Gromowych Urwisk na niższym wzniesieniu, obok wind.', 0),
(5485, 'koKR', 'Natura daje nam wszystko, czego potrzebujemy. Porozmawiaj z Kominem Zimowe Kopyto w „Holistycznym Zielarstwie” na środkowym wzniesieniu.', 'Natura daje nam wszystko, czego potrzebujemy. Porozmawiaj z Kominem Zimowe Kopyto w „Holistycznym Zielarstwie” na środkowym wzniesieniu.', 0),
(5486, 'koKR', 'Każdy przyjaciel zwierząt jest moim przyjacielem. Szukasz Sali Łowców. Stoi na szczycie Wzniesienia Myśliwego.', 'Każdy przyjaciel zwierząt jest moim przyjacielem. Szukasz Sali Łowców. Stoi na szczycie Wzniesienia Myśliwego.', 0),
(5487, 'koKR', 'Jest pewna symetria w tym, że skóra twojego wroga daje ci ochronę. Aby rozwinąć umiejętności garbarskie, odszukaj Unę w Płatnerzach Gromowych Urwisk na środkowym wzniesieniu.', 'Jest pewna symetria w tym, że skóra twojego wroga daje ci ochronę. Aby rozwinąć umiejętności garbarskie, odszukaj Unę w Płatnerzach Gromowych Urwisk na środkowym wzniesieniu.', 0),
(5488, 'koKR', 'Smutno pomyśleć, co spotkało te biedne nieumarłe dusze. Arcymaga Shymma znajdziesz pogrążonego w zadumie przy Źródłach Objawień, pod Wzniesieniem Ducha.', 'Smutno pomyśleć, co spotkało te biedne nieumarłe dusze. Arcymaga Shymma znajdziesz pogrążonego w zadumie przy Źródłach Objawień, pod Wzniesieniem Ducha.', 0),
(5489, 'koKR', 'Matka Ziemia skrywa wiele tajemnic, a Brek Kamienne Kopyto może ci pomóc odkryć niektóre z nich. Znajdziesz go na niższym wzniesieniu, w Geologii Kamiennego Kopyta.', 'Matka Ziemia skrywa wiele tajemnic, a Brek Kamienne Kopyto może ci pomóc odkryć niektóre z nich. Znajdziesz go na niższym wzniesieniu, w Geologii Kamiennego Kopyta.', 0),
(5490, 'koKR', 'Mimo swojej tragedii nieumarli przebyli całą tę drogę, by nam pomóc. Mam tylko nadzieję, że i my zdołamy im pomóc. Odszukaj Ojca Cobba przy Źródłach Objawień, pod Wzniesieniem Ducha.', 'Mimo swojej tragedii nieumarli przebyli całą tę drogę, by nam pomóc. Mam tylko nadzieję, że i my zdołamy im pomóc. Odszukaj Ojca Cobba przy Źródłach Objawień, pod Wzniesieniem Ducha.', 0),
(5491, 'koKR', 'Matka Ziemia wzywa, a ty odpowiadasz. Salę Duchów znajdziesz na Wzniesieniu Ducha.', 'Matka Ziemia wzywa, a ty odpowiadasz. Salę Duchów znajdziesz na Wzniesieniu Ducha.', 0),
(5492, 'koKR', 'Każdy wykorzystany skrawek sprawia, że mniej marnujemy, i przybliża nas do Matki Ziemi. Mooranta pokaże ci drogę. Szukaj jej tuż przed Płatnerzami Gromowych Urwisk na środkowym wzniesieniu.', 'Każdy wykorzystany skrawek sprawia, że mniej marnujemy, i przybliża nas do Matki Ziemi. Mooranta pokaże ci drogę. Szukaj jej tuż przed Płatnerzami Gromowych Urwisk na środkowym wzniesieniu.', 0),
(5494, 'koKR', 'Odziewanie plemienia to praca równie ważna jak każda inna. Poszukaj Tepy w Płatnerzach Gromowych Urwisk. Igła jest jej posłuszna jak mało komu.', 'Odziewanie plemienia to praca równie ważna jak każda inna. Poszukaj Tepy w Płatnerzach Gromowych Urwisk. Igła jest jej posłuszna jak mało komu.', 0),
(5496, 'koKR', 'Silny ciałem i duchem. Nie ma potężniejszego połączenia! Odkryj swoje przeznaczenie u Sarka Gniewny Totem w Sali Łowców.', 'Silny ciałem i duchem. Nie ma potężniejszego połączenia! Odkryj swoje przeznaczenie u Sarka Gniewny Totem w Sali Łowców.', 0),
(5497, 'koKR', 'Ach, szybować z wielkimi ptakami nieba. Odszukaj Tala na szczycie Gniazda wiwern. Skieruje cię tam, dokąd zmierzasz.', 'Ach, szybować z wielkimi ptakami nieba. Odszukaj Tala na szczycie Gniazda wiwern. Skieruje cię tam, dokąd zmierzasz.', 0),
(5498, 'koKR', 'Karczmarki Pali szukaj w budynku tuż na południe od Banku Gromowych Urwisk, na niższym wzniesieniu.', 'Karczmarki Pali szukaj w budynku tuż na południe od Banku Gromowych Urwisk, na niższym wzniesieniu.', 0),
(5499, 'koKR', 'Karczmarka Pala pomoże ci dać odpocząć ciału i duchowi. Znajdziesz ją w budynku tuż na południe od banku, na niższym wzniesieniu.', 'Karczmarka Pala pomoże ci dać odpocząć ciału i duchowi. Znajdziesz ją w budynku tuż na południe od banku, na niższym wzniesieniu.', 0),
(5500, 'koKR', 'Skrzynkę pocztową znajdziesz tuż przed Bankiem Gromowych Urwisk, na niższym wzniesieniu.', 'Skrzynkę pocztową znajdziesz tuż przed Bankiem Gromowych Urwisk, na niższym wzniesieniu.', 0),
(5501, 'koKR', 'Zdaje się, że niedawno dostarczono nową pocztę. Skrzynkę pocztową znajdziesz tuż przed Bankiem Gromowych Urwisk, na niższym wzniesieniu.', 'Zdaje się, że niedawno dostarczono nową pocztę. Skrzynkę pocztową znajdziesz tuż przed Bankiem Gromowych Urwisk, na niższym wzniesieniu.', 0),
(5502, 'koKR', 'Znajduje się w najniższej części Gromowych Urwisk. Szukaj w pobliżu banku. To niedaleko stamtąd.', 'Znajduje się w najniższej części Gromowych Urwisk. Szukaj w pobliżu banku. To niedaleko stamtąd.', 0),
(5503, 'koKR', 'Dom aukcyjny znajdziesz na centralnej iglicy Gromowych Urwisk. Szukaj u stóp Wieży Wiwern. Niech czuwają nad tobą przodkowie.', 'Dom aukcyjny znajdziesz na centralnej iglicy Gromowych Urwisk. Szukaj u stóp Wieży Wiwern. Niech czuwają nad tobą przodkowie.', 0),
(5745, 'koKR', 'Słucham i słucham, ale nie słyszę tych duchów, o których mówi Karn.', '', 0),
(7214, 'koKR', 'Witaj, $N. Możesz rozmawiać ze mną, chyba że masz sprawę bezpośrednio do mojej pani, Magaty.$B$BZałatwiam za nią większość spraw, by mogła skupić się na ważniejszych kwestiach. Może jest coś, co moglibyśmy omówić, zanim poprosisz ją o posłuchanie?', '', 0),
(7254, 'koKR', 'Ach, szukasz mądrości Ansekhwy. Znajdziesz go na niższym wzniesieniu, w Orężu Gromowych Urwisk.', 'Ach, szukasz mądrości Ansekhwy. Znajdziesz go na niższym wzniesieniu, w Orężu Gromowych Urwisk.', 0),
(7255, 'koKR', 'Nikt nie włada bronią tak biegle jak Ansekhwa. Mówi się, że prowadzą go duchy najwspanialszych wojowników spośród naszych czcigodnych przodków. Odszukaj go na niższym wzniesieniu, a nauczy cię tego, czego chcesz się dowiedzieć.', 'Nikt nie włada bronią tak biegle jak Ansekhwa. Mówi się, że prowadzą go duchy najwspanialszych wojowników spośród naszych czcigodnych przodków. Odszukaj go na niższym wzniesieniu, a nauczy cię tego, czego chcesz się dowiedzieć.', 0),
(7584, 'koKR', 'Czasy, w których żyjemy, są zmienne jak kapryśne wiatry, $N. Sama ziemia drży i krzyczy w udręce. Musimy pozostać niezłomni, inaczej i nas pochłonie zamęt.', '', 0),
(7704, 'koKR', 'Bena pracuje jak opętana. Dniem i nocą widzę ją pochyloną nad tymi miksturami, często bez snu i jedzenia. Wiem, że nasi nieumarli sprzymierzeńcy potrzebują pomocy, ale zaczynam się bać, że zrobi sobie krzywdę.', '', 0),
(7743, 'koKR', '', 'Gdy po raz pierwszy ujrzałam nieumarłych, zapłakałam, bo nie potrafiłam sobie wyobrazić ich grozy i samotności. Wtedy przemówiła do mnie Matka Ziemia; zaśpiewała w mojej krwi. I powiedziała mi: „Ocal ich”.', 0),
(7883, 'koKR', 'Czego bym nie dał, by w taki dzień być na otwartych równinach... ale obowiązek mnie wiąże.', '', 0),
(7912, 'koKR', 'Zaklinanie jest w naszej rodzinie od pokoleń. Uczyłem się od najmłodszych lat, tak jak teraz mój syn.', '', 0),
(7973, 'koKR', 'Podobno mieszka tu sam Kairn. Gdy skończę wykonywać godny dar, odszukam go. Może udzieli mi mądrych słów.', '', 0),
(8009, 'koKR', 'Mój topór widział wiele bitew i lubię mieć go pod ręką. Wrogie siły kilka razy już przebiły się do naszej stolicy, ale bez obaw: zawsze je odpieraliśmy.', '', 0),
(8046, 'koKR', '', 'Igła jest mała, ale nić mocna, a ściegi drobne. Nasze przymierze z Thrallem i pozostałymi przetrwa. Nikt nie wypędzi Hordy z tych ziem.', 0),
(8074, 'koKR', 'Nie marnujemy żadnej części zwierząt, na które polujemy.', '', 0),
(8112, 'koKR', 'Pustkowia, z ich palącym słońcem i wrogimi mieszkańcami, to doskonałe miejsce, by sprawdzić swoją siłę i wytrwałość.', '', 0),
(8114, 'koKR', 'Witaj. Jeśli szukasz wyrobów ze skóry, przekonasz się, że moje towary są dobrze wykonane.', '', 0),
(8116, 'koKR', 'Kto dosiada wiwerny, ten widzi, że słynie ona z siły i szybkości nie bez powodu.', '', 0),
(8168, 'koKR', '', 'Czyż te wzory nie są piękne? Każdy przemawia własnym głosem.', 0),
(8516, 'koKR', 'Potrzebujesz pomocy Bulruga. Znajdziesz go na zewnątrz, na niższym wzniesieniu, między karczmą a Bankiem Gromowych Urwisk.', 'Potrzebujesz pomocy Bulruga. Znajdziesz go na zewnątrz, na niższym wzniesieniu, między karczmą a Bankiem Gromowych Urwisk.', 0),
(8517, 'koKR', 'Twoja troska o dobro zwierzęcych towarzyszy jest godna pochwały. Bulrug z niższego wzniesienia może ci w tym pomóc. Szukaj go między bankiem a karczmą.', 'Twoja troska o dobro zwierzęcych towarzyszy jest godna pochwały. Bulrug z niższego wzniesienia może ci w tym pomóc. Szukaj go między bankiem a karczmą.', 0),
(8677, 'koKR', 'Niech Matka Ziemia czuwa nad nami, pod osłoną nocy tak jak za dnia. Niech ten ogień rozświetli nasze ciała i duchy i przypomni nam o czcigodnych przodkach, którzy są zawsze obecni i prowadzą nas naszą drogą.\n', '', 0),
(8866, 'koKR', 'Z zaszczytem nauczę cię władać bronią, którą opanowałem, jeśli masz w sobie zdolność, by się tego nauczyć.', '', 0),
(8868, 'koKR', 'Jeśli potrzebujesz dalszego szkolenia, chętnie powiem ci, kto może ci pomóc. Jaka broń wpadła ci w oko?', '', 0),
(9009, 'koKR', 'Przodkowie uczą nas, że choć jednostka musi być silna, bezpieczeństwo tkwi we wspólnocie. Czy chcesz bronić honoru Gromowych Urwisk, zakładając gildię?', '', 0),
(9891, 'koKR', 'Witaj, $gbracie:siostro;... Jeśli pozwolisz, chciałbym zająć ci chwilę.$B$BMy, taureni, wiele przeszliśmy w trudach i próbach, zakładając naszą ojczyznę. Teraz brakuje nam dotkliwie tkanin. Jeśli możesz się nimi podzielić, proszę, przekaż je nam. Pomagając nam, z pewnością zyskasz wdzięczność taurenów na całym świecie!', '', 0),
(18607, 'koKR', 'Idź na Wzniesienie Myśliwego. Znajdziesz tam mistrzów bitewnych.', 'Idź na Wzniesienie Myśliwego. Znajdziesz tam mistrzów bitewnych.', 0),
(20606, 'koKR', 'Zarówno Hanashi, jak i Sayoc mogą cię nauczyć władania toporami jedno- i dwuręcznymi. Znajdziesz ich w Dolinie Honoru w Orgrimmarze.', 'Zarówno Hanashi, jak i Sayoc mogą cię nauczyć władania toporami jedno- i dwuręcznymi. Znajdziesz ich w Dolinie Honoru w Orgrimmarze.', 0),
(20608, 'koKR', 'Mistrzowie broni w Dolinie Honoru w Orgrimmarze, Sayoc i Hanashi, mogą cię nauczyć strzelania z łuku. Znawczynią jest też Ileda, mistrzyni broni Srebrnej Luny z Placu Obieżyświatów.', 'Mistrzowie broni w Dolinie Honoru w Orgrimmarze, Sayoc i Hanashi, mogą cię nauczyć strzelania z łuku. Znawczynią jest też Ileda, mistrzyni broni Srebrnej Luny z Placu Obieżyświatów.', 0),
(20610, 'koKR', 'Walki sztyletami uczy trzech mistrzów broni: Archibald w Dzielnicy Wojennej Podmiasta, Sayoc w Dolinie Honoru w Orgrimmarze i Ileda na Placu Obieżyświatów w Srebrnej Lunie.', 'Walki sztyletami uczy trzech mistrzów broni: Archibald w Dzielnicy Wojennej Podmiasta, Sayoc w Dolinie Honoru w Orgrimmarze i Ileda na Placu Obieżyświatów w Srebrnej Lunie.', 0),
(20612, 'koKR', 'Walki bronią pięściową uczy Sayoc, orkowy mistrz broni w Orgrimmarze. Spędza dni w Dolinie Honoru.', 'Walki bronią pięściową uczy Sayoc, orkowy mistrz broni w Orgrimmarze. Spędza dni w Dolinie Honoru.', 0),
(20620, 'koKR', 'Sayoc i Hanashi, mistrzowie broni Orgrimmaru, to prawdziwi artyści broni miotanej. Szkolą chętnych uczniów w Dolinie Honoru. Jeśli jednak chodzi o czystą finezję w tej sztuce, nikt nie dorówna Iledzie z Placu Obieżyświatów w Srebrnej Lunie.', 'Sayoc i Hanashi, mistrzowie broni Orgrimmaru, to prawdziwi artyści broni miotanej. Szkolą chętnych uczniów w Dolinie Honoru. Jeśli jednak chodzi o czystą finezję w tej sztuce, nikt nie dorówna Iledzie z Placu Obieżyświatów w Srebrnej Lunie.', 0),
(34745, 'koKR', '%s cicho się śmieje.', '', 0),
(34746, 'koKR', 'No dobrze, Aponi. Mam dość myśli, żeby się nimi podzielić. Rozmawiałaś kiedyś z elfami z Gaju Luny?', '', 0),
(34747, 'koKR', 'Wiesz, że elfy mówią o bogini księżyca? Wielką wagę przywiązują do światła, które daje księżyc.', '', 0),
(34748, 'koKR', 'Właśnie tak jak Mu\'sha. Podobieństwa, o których słyszałem, są ciekawe. I nie jest tajemnicą, że wszyscy druidzi, zarówno shu\'halo, jak i elfy, mogą przyzywać światło Mu\'shy.', '', 0),
(34749, 'koKR', 'Zastanawiam się. Hamuul dobrze nas prowadził i wiele się od niego nauczyłem. Legendy mówią, że nasz lud był druidami od zarania czasu...', '', 0),
(34750, 'koKR', '...ale to, czego uczy Hamuul, to wiedza elfów. Nocnych elfów. Przywiązują tak wielką wagę do swojej bogini księżyca, bo są istotami nocy.', '', 0),
(34751, 'koKR', 'Nie! Nie, nic z tych rzeczy. Nie bez powodu jest starszym, siostro. Mu\'sha to jedno z oczu Matki Ziemi i czuwa nad nami. W tym nie ma nic złowrogiego.', '', 0),
(34753, 'koKR', 'Ale przecież jesteśmy ludem, który przede wszystkim dąży do równowagi. Nasi wojownicy walczą tylko wtedy, gdy trzeba. Nasi łowcy biorą tylko tyle, ile plemiona potrzebują do życia, i wykorzystują wszystko, co się da. Szamani są przewodnikami i pośrednikami duchów żywiołów.', '', 0),
(34754, 'koKR', 'I choć my, druidzi, jesteśmy strażnikami natury, zastanawiam się, czy nie przeoczyliśmy kluczowego aspektu równowagi we wszystkim.', '', 0),
(34755, 'koKR', 'Nie, nie. Nie ma potrzeby zawracać mu głowy jałowym filozofowaniem ucznia, kiedy podejmuje przyjaciela.', '', 0),
(34756, 'koKR', 'Cóż, to nie jest zupełnie nowa myśl, siostro.', '', 0),
(34757, 'koKR', 'Na pewno $gbyłeś:byłaś; kiedyś $guczniem:uczennicą;, $N. $gUczyłeś:Uczyłaś; się od nauczyciela i w jakiś sposób $gnabrałeś:nabrałaś; do niego szacunku, prawda? Może nie jako do osoby, ale przynajmniej jako do kogoś, kto wiedział więcej od ciebie i chciał cię uczyć. Jeśli nie, użyj wyobraźni...$b$bCo byś $gzrobił:zrobiła;, gdybyś $gzrozumiał:zrozumiała;, że twój nauczyciel może nie wiedzieć tyle, ile $gmyślałeś:myślałaś;, i że być może $gznalazłeś:znalazłaś; lepszą ścieżkę?', '', 0),
(34758, 'koKR', '', 'To okropne! Nie powinnam tu siedzieć bezużyteczna, kiedy jest tyle do zrobienia! Gdyby tylko moje ramię nie zostało zranione w Północnej Grani... Ale nie ma co się nad tym rozwodzić! Tahu w końcu mnie połata i wyleczy, a tymczasem i tak będziemy tu pomagać.\nTo, że nie jesteśmy na froncie, nie znaczy, że nie możemy jakoś pomóc.', 0),
(34762, 'koKR', '', 'Porozmawiaj ze mną, Tahu. O czymkolwiek. O czymś! Zaraz tu zwariuję.', 0),
(34763, 'koKR', '', 'Niewiele.', 0),
(34764, 'koKR', '', 'Jak Mu\'sha.', 0),
(34765, 'koKR', '', 'Do czego zmierzasz?', 0),
(34766, 'koKR', '', 'Słyszę w twoim głosie to „ale”...', 0),
(34767, 'koKR', '', 'Myślisz, że jego nauki są błędne?', 0),
(34768, 'koKR', '', 'To poruszysz ten temat ze starszym?', 0),
(34769, 'koKR', '', 'Chyba tak. Ale to, co powiedziałeś, nie jest głupie.', 0),
(34770, 'koKR', '', 'Widzę tę zamyśloną zmarszczkę, Tahu.', 0),
(34771, 'koKR', '', 'Ale coś cię gryzie, prawda?', 0),
(34772, 'koKR', '', 'Co z nim?', 0),
(34773, 'koKR', '', 'Jest takie powiedzenie... „Najciemniej jest przed świtem”. Ale świt nadejdzie, Tahu. Słońce wzejdzie. Równowaga wróci tam, gdzie powinna być.', 0),
(34774, 'koKR', '', '%s uśmiecha się i wskazuje na północ.', 0),
(34775, 'koKR', '', 'Nawet na samym lodowcu słońce zdoła przebić się przez mrok. Mam nadzieję, Tahu. Myślę, że przez to przejdziemy, choćby wyglądało nie wiem jak źle.', 0),
(34776, 'koKR', '', 'Ale i tak wolałabym być tam, na pierwszej linii, i pomagać, żeby to się stało, niż próbować uspokajać się wiarą. Nie możemy tylko siedzieć i mieć nadzieję.', 0),
(34777, 'koKR', '', 'I dzięki tej nadziei wzmocnić naszą stronę w walce?', 0),
(34778, 'koKR', 'Wybacz, siostro. Nie ma się czym martwić.', '', 0),
(34779, 'koKR', 'Myślę o froncie na północy. Tym, na który tak chcesz wrócić.', '', 0),
(34780, 'koKR', 'Wiem, że doradzam cierpliwość, Aponi, ale nie lubię tu tkwić bardziej niż ty. Czasy są ponure, a bezczynność tylko każe mi się martwić, że to moja bezczynna ręka mogła odwrócić bieg wydarzeń.', '', 0),
(34781, 'koKR', 'A jednak... we wszystkim jest równowaga, nawet w śmierci. Po prostu nie znoszę myśli, że takie zniszczenie i mrok mogą być konieczne.', '', 0),
(34783, 'koKR', 'Wiem, siostro. Wiem. Kiedyś wrócimy do walki. Ale na razie może najlepiej nieść słowo innym... dać im nadzieję, którą masz ty.', '', 0),
(34784, 'koKR', 'O to właśnie chodzi.', '', 0),
(35040, 'koKR', 'Wierzysz w to? W końcu otworzyli dla nas to miejsce, żebyśmy mogli tędy latać sterowcem! Koniec ze strefą zakazu lotów, co nie? Podczas lotu próbnego rozbiliśmy o urwisko tylko jeden sterowiec. Nie rozumiem, czym oni się tak martwili.', '', 0),
(35041, 'koKR', 'Podchodźcie śmiało! Przybył sterowiec do Orgrimmaru! Wszyscy na pokład, lecimy do Durotaru!', '', 0),
(35141, 'koKR', 'Krendlego Wielkokieszenia znajdziesz przy lądowisku sterowca na zachodnim krańcu Wzniesienia Ducha. Nie przepadam za tą goblińską machiną, która tędy lata... ale zawiezie cię do Orgrimmaru, jeśli ją zniesiesz.', 'Krendlego Wielkokieszenia znajdziesz przy lądowisku sterowca na zachodnim krańcu Wzniesienia Ducha. Nie przepadam za tą goblińską machiną, która tędy lata... ale zawiezie cię do Orgrimmaru, jeśli ją zniesiesz.', 0),
(43833, 'koKR', 'Światło Słońca rozjaśnia ścieżkę do mądrości. Którędy pójdziemy dziś, przyjacielu?', 'Światło Słońca rozjaśnia ścieżkę do mądrości. Którędy pójdziemy dziś, przyjacielu?', 0);
